# -----------------------------------------------------------------------------
# 8.2 Mapping für abweichende Sprachcodes (Whisper → Übersetzungs-APIs)
# -----------------------------------------------------------------------------
# ACHTUNG: Dieses Mapping wird NUR für Übersetzungs-Engines (Google, Argos, Ollama)
#          verwendet, NICHT für die Whisper-Transkription!
#          Whisper erwartet die originalen ISO-Codes (z. B. 'tl' für Tagalog).
LANGUAGE_CODE_MAPPING: Dict[str, str] = {
    "yue": "zh-TW",   # Kantonesisch → Traditionelles Chinesisch (Google)
    "tl": "fil",      # Tagalog → Filipino (Google)
    "he": "iw",       # Hebräisch → iw (Google)
    "zh": "zh-CN",    # Chinesisch (vereinfacht) → zh-CN (Google)
}

# -----------------------------------------------------------------------------
# 8.3 Von Whisper direkt unterstützte Sprachcodes (ohne "auto")
# -----------------------------------------------------------------------------
WHISPER_SUPPORTED_LANGUAGES: Set[str] = {
    code for code in BASE_LANGUAGES if code != "auto"
}

# -----------------------------------------------------------------------------
# 8.4 Abgeleitete Strukturen (nicht manuell ändern)
# -----------------------------------------------------------------------------
SUPPORTED_LANGUAGES: Dict[str, str] = BASE_LANGUAGES.copy()
# Liste von Tupeln (Anzeigename, Code), sortiert nach Anzeigename
SORTED_LANGUAGES: List[Tuple[str, str]] = sorted(
    ((name, code) for code, name in BASE_LANGUAGES.items()), key=lambda x: x[0]
)
# Kurzformen (max. 3 Zeichen) für Anzeige in GUI
LANGUAGE_SHORT_CODES: Dict[str, str] = {
    code: name[:3] for code, name in BASE_LANGUAGES.items()
}
# Reverse-Mapping für schnelle Suche: Anzeigename → Code
DISPLAY_NAME_TO_CODE: Dict[str, str] = {
    name: code for code, name in BASE_LANGUAGES.items()
}

# -----------------------------------------------------------------------------
# 8.5 Hilfsfunktionen für konsistenten Sprachcode‑Zugriff
# -----------------------------------------------------------------------------
def get_whisper_language_code(display_name: str) -> Optional[str]:
    """
    Gibt den Whisper‑Code für einen Anzeigenamen zurück.

    Args:
        display_name: Der lesbare Name der Sprache (z. B. 'Deutsch').

    Returns:
        Der zugehörige ISO‑Code (z. B. 'de') oder None, wenn nicht gefunden.
    """
    return DISPLAY_NAME_TO_CODE.get(display_name)


def get_display_name(code: str) -> str:
    """
    Gibt den lesbaren Namen für einen Sprachcode zurück.

    Args:
        code: Der Sprachcode (z. B. 'de').

    Returns:
        Der Anzeigename (z. B. 'Deutsch') oder der Code selbst, falls unbekannt.
    """
    return BASE_LANGUAGES.get(code, code)


def map_to_google_code(whisper_code: str) -> str:
    """
    Konvertiert einen Whisper‑Sprachcode in den von Google Translate erwarteten Code.

    Args:
        whisper_code: Der Whisper‑Code (z. B. 'tl', 'yue').

    Returns:
        Der für die Übersetzungs‑API geeignete Code (z. B. 'fil', 'zh-TW').
        Bei unbekannten Codes wird der Originalcode zurückgegeben.
    """
    if whisper_code == "auto":
        return "auto"
    return LANGUAGE_CODE_MAPPING.get(whisper_code, whisper_code)


def is_whisper_language_code(code: str) -> bool:
    """
    Prüft, ob ein gegebener Code von Whisper direkt unterstützt wird.

    Args:
        code: Der zu prüfende Sprachcode (z. B. 'de', 'tl').

    Returns:
        True, wenn Whisper diesen Code akzeptiert, sonst False.
    """
    return code in WHISPER_SUPPORTED_LANGUAGES


def is_valid_source_language(display_name: str) -> bool:
    """
    Prüft, ob ein Anzeigename eine gültige Quellsprache für Whisper ist.

    Args:
        display_name: Der lesbare Name (z. B. 'Deutsch' oder 'Automatisch').

    Returns:
        True, wenn der Name in der Sprachliste existiert (einschließlich 'auto').
    """
    return display_name in DISPLAY_NAME_TO_CODE


# -----------------------------------------------------------------------------
# 8.6 Vordefinierte Gruppen für die GUI (Common, Asian, More)
# -----------------------------------------------------------------------------
# Diese Gruppen werden im WhisperLayoutManager für die übersichtliche Darstellung
# der Zielsprachen verwendet.
COMMON_LANGUAGE_CODES: List[str] = [
    "de", "en", "fr", "es", "it", "pt", "nl", "pl", "ru"
]
ASIAN_LANGUAGE_CODES: List[str] = [
    "ja", "zh", "ko", "vi", "th", "id", "tl", "hi", "ar", "fa", "tr"
]

# Für bessere Performance: Vorberechnete Namenslisten (nur einmal initialisiert)
_COMMON_NAMES: Optional[List[str]] = None
_ASIAN_NAMES: Optional[List[str]] = None
_OTHER_NAMES: Optional[List[str]] = None


def get_common_language_names() -> List[str]:
    """Gibt die lesbaren Namen der häufigsten Sprachen zurück (mit Caching)."""
    global _COMMON_NAMES
    if _COMMON_NAMES is None:
        _COMMON_NAMES = [
            BASE_LANGUAGES[code] for code in COMMON_LANGUAGE_CODES
            if code in BASE_LANGUAGES
        ]
    return _COMMON_NAMES.copy()


def get_asian_language_names() -> List[str]:
    """Gibt die lesbaren Namen asiatischer / nahöstlicher Sprachen zurück (mit Caching)."""
    global _ASIAN_NAMES
    if _ASIAN_NAMES is None:
        _ASIAN_NAMES = [
            BASE_LANGUAGES[code] for code in ASIAN_LANGUAGE_CODES
            if code in BASE_LANGUAGES
        ]
    return _ASIAN_NAMES.copy()


def get_other_language_names() -> List[str]:
    """
    Gibt alle übrigen lesbaren Sprachnamen zurück, die nicht in den
    vordefinierten Gruppen sind (mit Caching).
    """
    global _OTHER_NAMES
    if _OTHER_NAMES is None:
        excluded = set(COMMON_LANGUAGE_CODES + ASIAN_LANGUAGE_CODES)
        # SORTED_LANGUAGES enthält Tupel (name, code)
        _OTHER_NAMES = [
            name for name, code in SORTED_LANGUAGES
            if code not in excluded and code != "auto"
        ]
    return _OTHER_NAMES.copy()


# =============================================================================
# 9. BASISKLASSEN UND HILFSKLASSEN (EventBus, PeriodicTaskMixin, BaseDialog, ContextMenuMixin, Themes, Fonts)
# =============================================================================
class EventBus:
    """
    Thread-sicherer Event-Bus mit exakten und Muster-Abonnements.
    Optional kann ein Scheduler (z. B. tkinter.root.after) übergeben werden,
    um Callbacks immer im Hauptthread auszuführen.

    Features:
        - Thread-sichere Subscription/Unsubscription
        - Muster-basierte Abonnements (Wildcards mit fnmatch)
        - Optionaler Scheduler für Hauptthread-Ausführung
        - Detaillierte Debug- und Metrik-Funktionen
        - Kontext-Manager für temporäre Subscriptions
    """

    def __init__(
        self,
        debug: bool = False,
        scheduler: Optional[Callable[[Callable, int], None]] = None,
    ) -> None:
        """
        Initialisiert den EventBus.

        Args:
            debug: Aktiviert Debug‑Logging und Metriken.
            scheduler: Funktion, die einen Callback und eine Verzögerung in ms erwartet
                       und ihn im Hauptthread ausführt (z. B. root.after).
                       Wird None übergeben, werden Callbacks direkt aufgerufen.
        """
        self._lock = threading.RLock()
        self._exact: Dict[str, List[Callable]] = defaultdict(list)
        self._patterns: List[Tuple[str, Callable]] = []
        self._debug = debug
        self._metrics_enabled = debug
        self._metrics: Dict[str, Any] = {
            "total_events": 0,
            "events_per_type": defaultdict(int),
            "errors": 0,
            "start_time": time.time(),
        }
        self._scheduler = scheduler

        if debug:
            logger.debug("EventBus initialisiert (debug=True)")

    # -------------------------------------------------------------------------
    # Scheduler
    # -------------------------------------------------------------------------
    def set_scheduler(self, scheduler: Callable[[Callable, int], None]) -> None:
        """
        Setzt einen Scheduler, der alle Callbacks in den Hauptthread verschiebt.
        Der Scheduler muss die Signatur (delay_ms, callback, *args) haben.

        Args:
            scheduler: Scheduler-Funktion (z. B. lambda delay, cb, *args: root.after(delay, cb, *args))
        """
        with self._lock:
            self._scheduler = scheduler
        if self._debug:
            logger.debug("EventBus: Scheduler gesetzt")

    # -------------------------------------------------------------------------
    # Abonnements
    # -------------------------------------------------------------------------
    def subscribe(self, event_type: str, callback: Callable[[Any], None]) -> None:
        """
        Abonniert einen exakten Event-Typ.

        Args:
            event_type: Der Event-Typ (z. B. 'transcription').
            callback: Callback, der mit den Event-Daten aufgerufen wird.
        """
        with self._lock:
            self._exact[event_type].append(callback)
        if self._debug:
            logger.debug(f"EventBus: Subscribed to '{event_type}'")

    def subscribe_pattern(self, pattern: str, callback: Callable[[Any], None]) -> None:
        """
        Abonniert ein Muster (Wildcard) mit fnmatch.

        Args:
            pattern: Muster wie 'model_*' oder 'audio_*'.
            callback: Callback, der bei passendem Event-Typ aufgerufen wird.
        """
        with self._lock:
            self._patterns.append((pattern, callback))
        if self._debug:
            logger.debug(f"EventBus: Subscribed to pattern '{pattern}'")

    def unsubscribe(self, event_type: str, callback: Callable) -> bool:
        """
        Entfernt ein exaktes Abonnement.

        Args:
            event_type: Event-Typ.
            callback: Die zu entfernende Callback-Funktion.

        Returns:
            True, wenn das Abonnement existierte und entfernt wurde, sonst False.
        """
        with self._lock:
            if event_type not in self._exact:
                return False
            try:
                self._exact[event_type].remove(callback)
                if not self._exact[event_type]:
                    del self._exact[event_type]
                if self._debug:
                    logger.debug(f"EventBus: Unsubscribed from '{event_type}'")
                return True
            except ValueError:
                return False

    def unsubscribe_pattern(self, pattern: str, callback: Callable) -> bool:
        """
        Entfernt ein Muster-Abonnement.

        Args:
            pattern: Das Muster.
            callback: Die zu entfernende Callback-Funktion.

        Returns:
            True, wenn das Abonnement existierte und entfernt wurde, sonst False.
        """
        with self._lock:
            for i, (p, cb) in enumerate(self._patterns):
                if p == pattern and cb == callback:
                    del self._patterns[i]
                    if self._debug:
                        logger.debug(f"EventBus: Unsubscribed from pattern '{pattern}'")
                    return True
            return False

    # -------------------------------------------------------------------------
    # Events senden
    # -------------------------------------------------------------------------
    def emit(self, event_type: str, data: Any = None) -> None:
        """
        Sendet ein Event an alle Abonnenten.
        Callbacks werden ggf. über den Scheduler im Hauptthread ausgeführt.

        Args:
            event_type: Der Event-Typ.
            data: Beliebige Daten, die an die Callbacks übergeben werden.
        """
        if self._metrics_enabled:
            with self._lock:
                self._metrics["total_events"] += 1
                self._metrics["events_per_type"][event_type] += 1

        if self._debug:
            logger.debug(f"EventBus: Emitting '{event_type}'")

        # Kopie der Callbacks unter Lock erstellen, um Mutation während Iteration zu vermeiden
        with self._lock:
            exact_callbacks = list(self._exact.get(event_type, []))
            pattern_callbacks = list(self._patterns)

        def run_callback(cb: Callable, d: Any) -> None:
            """Führt einen einzelnen Callback aus und fängt Fehler ab."""
            try:
                cb(d)
            except Exception as e:
                logger.error(
                    f"EventBus callback error for '{event_type}': {e}", exc_info=True
                )
                if self._metrics_enabled:
                    with self._lock:
                        self._metrics["errors"] += 1

        if self._scheduler is not None:
            # Scheduler vorhanden → alle Callbacks in den Hauptthread delegieren
            for cb in exact_callbacks:
                self._scheduler(0, run_callback, cb, data)
            for pattern, cb in pattern_callbacks:
                if fnmatch.fnmatch(event_type, pattern):
                    self._scheduler(0, run_callback, cb, data)
        else:
            # Kein Scheduler → Callbacks direkt ausführen (im aktuellen Thread)
            for cb in exact_callbacks:
                run_callback(cb, data)
            for pattern, cb in pattern_callbacks:
                if fnmatch.fnmatch(event_type, pattern):
                    run_callback(cb, data)

    # -------------------------------------------------------------------------
    # Kontext-Manager
    # -------------------------------------------------------------------------
    @contextmanager
    def subscription_context(self, event_type: str, callback: Callable[[Any], None]):
        """
        Kontext-Manager für temporäre Subscriptions.
        Das Abonnement wird am Ende des Blocks automatisch entfernt.

        Beispiel:
            with event_bus.subscription_context("progress", on_progress):
                # hier werden Events empfangen
        """
        self.subscribe(event_type, callback)
        try:
            yield
        finally:
            self.unsubscribe(event_type, callback)

    @contextmanager
    def pattern_subscription_context(
        self, pattern: str, callback: Callable[[Any], None]
    ):
        """Kontext-Manager für temporäre Muster-Abonnements."""
        self.subscribe_pattern(pattern, callback)
        try:
            yield
        finally:
            self.unsubscribe_pattern(pattern, callback)

    # -------------------------------------------------------------------------
    # Verwaltung
    # -------------------------------------------------------------------------
    def clear(self) -> None:
        """Entfernt alle Abonnements."""
        with self._lock:
            self._exact.clear()
            self._patterns.clear()
        if self._debug:
            logger.debug("EventBus: All subscriptions cleared")

    def get_metrics(self) -> Dict[str, Any]:
        """
        Gibt Metriken zurück (nur wenn debug=True aktiviert).

        Returns:
            Dictionary mit total_events, events_per_type, errors, uptime.
            Bei deaktivierten Metriken leeres Dictionary.
        """
        if not self._metrics_enabled:
            return {}
        with self._lock:
            metrics = self._metrics.copy()
            metrics["uptime"] = time.time() - metrics["start_time"]
            metrics["events_per_type"] = dict(metrics["events_per_type"])
            return metrics

    def get_debug_info(self) -> Dict[str, Any]:
        """
        Gibt detaillierte Debug-Informationen zurück (nur bei debug=True).

        Returns:
            Dictionary mit Anzahl exakter und Muster-Abonnements, Scheduler-Status, Metriken.
        """
        if not self._debug:
            return {"debug_enabled": False}
        with self._lock:
            return {
                "debug_enabled": True,
                "exact_subscriptions": {k: len(v) for k, v in self._exact.items()},
                "pattern_subscriptions": len(self._patterns),
                "has_scheduler": self._scheduler is not None,
                "metrics": self.get_metrics(),
            }

    def __repr__(self) -> str:
        with self._lock:
            exact_count = sum(len(v) for v in self._exact.values())
            pattern_count = len(self._patterns)
        return (
            f"<EventBus exact={exact_count} patterns={pattern_count} "
            f"scheduler={self._scheduler is not None}>"
        )


class PeriodicTaskMixin:
    def __init__(
        self,
        interval: float,
        task: Callable,
        *args,
        thread_name: Optional[str] = None,
        initial_delay: float = 0.0,
        max_errors: int = 0,
        on_error: Optional[Callable[[Exception], None]] = None,
        **kwargs,
    ):
        self._interval = interval
        self._task = task
        self._task_args = args
        self._task_kwargs = kwargs
        self._max_errors = max_errors
        self._on_error = on_error
        self._error_count = 0
        self._stop_event = threading.Event()
        self._thread = threading.Thread(
            target=self._run, daemon=True, name=thread_name or f"Periodic-{id(self)}"
        )
        self._initial_delay = initial_delay
        self._thread.start()

    def _run(self):
        if self._initial_delay > 0:
            self._sleep_with_stop(self._initial_delay)
            if self._stop_event.is_set():
                return

        while not self._stop_event.is_set():
            self._sleep_with_stop(self._interval)
            if self._stop_event.is_set():
                break

            try:
                self._task(*self._task_args, **self._task_kwargs)
                self._error_count = 0
            except Exception as e:
                logger.error(f"Periodic task error: {e}")
                if self._on_error:
                    self._on_error(e)
                self._error_count += 1
                if self._max_errors > 0 and self._error_count >= self._max_errors:
                    logger.error(
                        f"Max errors ({self._max_errors}) reached, stopping periodic task."
                    )
                    break

    def _sleep_with_stop(self, duration: float):
        chunk = 0.5
        while duration > 0 and not self._stop_event.is_set():
            sleep_time = min(chunk, duration)
            time.sleep(sleep_time)
            duration -= sleep_time

    def wait_for_stop(self, timeout: float = 2.0) -> bool:
        if self._thread.is_alive():
            self._thread.join(timeout=timeout)
            return not self._thread.is_alive()
        return True

    def stop_periodic_task(self, timeout: float = 2.0) -> None:
        self._stop_event.set()
        if self._thread.is_alive():
            self._thread.join(timeout=timeout)

    def is_running(self) -> bool:
        return not self._stop_event.is_set() and self._thread.is_alive()


class BaseDialog:
    """Basisklasse für Dialoge mit einheitlichem Theming, Zentrierung und Escape‑Schließen."""

    def __init__(
        self,
        parent: tk.Tk,
        title: str,
        width: int = 600,
        height: int = 500,
        timeout: Optional[int] = None,
        modal: bool = True,
    ):
        self.parent = parent
        self.dialog = tk.Toplevel(parent)
        self.dialog.title(f"🐉 {title}")
        self.dialog.geometry(f"{width}x{height}")
        self.dialog.configure(bg=CURRENT_THEME.BG_PRIMARY)
        if modal:
            self.dialog.transient(parent)
            self.dialog.grab_set()
        self.dialog.protocol("WM_DELETE_WINDOW", self.close)
        self.dialog.bind("<Escape>", lambda e: self.close())
        if timeout:
            self.dialog.after(timeout * 1000, self.close)

        self.dialog.update_idletasks()
        x = parent.winfo_x() + (parent.winfo_width() - self.dialog.winfo_width()) // 2
        y = parent.winfo_y() + (parent.winfo_height() - self.dialog.winfo_height()) // 2
        self.dialog.geometry(f"+{x}+{y}")

        self.main = tk.Frame(self.dialog, bg=CURRENT_THEME.BG_PRIMARY, padx=15, pady=15)
        self.main.pack(fill="both", expand=True)

        self.build_ui()

        if hasattr(parent, "_open_dialogs"):
            parent._open_dialogs.append(self.dialog)

    def build_ui(self):
        pass

    def _safe_after(
        self, delay: int, callback: Callable, *args, **kwargs
    ) -> Optional[str]:
        if self.dialog and self.dialog.winfo_exists():
            return self.dialog.after(delay, callback, *args, **kwargs)
        return None

    def close(self):
        if (
            hasattr(self.parent, "_open_dialogs")
            and self.dialog in self.parent._open_dialogs
        ):
            self.parent._open_dialogs.remove(self.dialog)
        try:
            self.dialog.destroy()
        except tk.TclError:
            pass


class ContextMenuMixin:
    """
    Einheitliches Kontextmenü für Text- und Entry-Widgets mit:
    - Umfangreichem Debug-Logging (nur bei DEBUG_LEVEL >= 3)
    - Robuster Fehlerbehandlung (keine GUI-Abstürze)
    - Unterstützung für ttk.Entry (indirekt)
    - Zusätzlichen Aktionen (Löschen, Alles auswählen)
    - Erkennung von leeren Auswahlen
    """

    def __init__(
        self, widget: Union[tk.Text, tk.Entry, ttk.Entry], use_copy_cut_paste: bool = True
    ):
        """
        Initialisiert das Kontextmenü.

        Args:
            widget: Das Ziel-Widget (tk.Text, tk.Entry oder ttk.Entry)
            use_copy_cut_paste: Ob Cut/Copy/Paste angeboten werden sollen
        """
        self.widget = widget
        self._debug = DEBUG_LEVEL >= 3
        self._widget_type = self._get_widget_type()
        
        # Menü erstellen
        self.menu = tk.Menu(
            widget,
            tearoff=0,
            bg=CURRENT_THEME.BG_TERTIARY,
            fg=CURRENT_THEME.TEXT_PRIMARY,
            activebackground=CURRENT_THEME.BG_HOVER,
            activeforeground=CURRENT_THEME.TEXT_ACCENT,
            borderwidth=1,
            relief="solid",
        )
        
        if use_copy_cut_paste:
            # Nur für Text-Widgets: Undo/Redo
            if self._widget_type == "text":
                self.menu.add_command(
                    label="Undo", command=self.undo, accelerator="Ctrl+Z"
                )
                self.menu.add_command(
                    label="Redo", command=self.redo, accelerator="Ctrl+Y"
                )
                self.menu.add_separator()
            
            # Standard-Aktionen
            self.menu.add_command(label="Cut", command=self.cut, accelerator="Ctrl+X")
            self.menu.add_command(label="Copy", command=self.copy, accelerator="Ctrl+C")
            self.menu.add_command(label="Paste", command=self.paste, accelerator="Ctrl+V")
            self.menu.add_separator()
        
        # Immer verfügbar
        self.menu.add_command(
            label="Select All", command=self.select_all, accelerator="Ctrl+A"
        )
        if self._widget_type == "text":
            self.menu.add_command(label="Delete", command=self.clear)
        
        self.menu.bind("<Escape>", lambda e: self.menu.unpost())
        widget.bind("<Button-3>", self.show_menu)
        
        if self._debug:
            log_debug("gui", f"ContextMenuMixin initialized for {self._widget_type} widget: {widget}")

    def _get_widget_type(self) -> str:
        """Ermittelt den Widget-Typ (text, entry, unknown)."""
        if isinstance(self.widget, tk.Text):
            return "text"
        if isinstance(self.widget, (tk.Entry, ttk.Entry)):
            return "entry"
        return "unknown"

    def _has_selection(self) -> bool:
        """Prüft, ob im Widget Text ausgewählt ist (robust)."""
        try:
            if self._widget_type == "text":
                return bool(self.widget.tag_ranges(tk.SEL))
            else:  # entry
                return self.widget.selection_present()
        except tk.TclError:
            return False

    def _get_selected_text(self) -> str:
        """Gibt den selektierten Text zurück oder leeren String."""
        try:
            if self._widget_type == "text":
                if self.widget.tag_ranges(tk.SEL):
                    return self.widget.get(tk.SEL_FIRST, tk.SEL_LAST)
            else:  # entry
                if self.widget.selection_present():
                    start = self.widget.index(tk.SEL_FIRST)
                    end = self.widget.index(tk.SEL_LAST)
                    return self.widget.get()[start:end]
        except tk.TclError as e:
            if self._debug:
                log_debug("gui", f"Error getting selected text: {e}")
        return ""

    def show_menu(self, event):
        """Zeigt das Kontextmenü an der Mausposition an."""
        try:
            self.menu.tk_popup(event.x_root, event.y_root)
            if self._debug:
                log_debug("gui", f"Context menu shown at ({event.x_root}, {event.y_root})")
        except Exception as e:
            if self._debug:
                log_debug("gui", f"Failed to show context menu: {e}")
        finally:
            self.menu.grab_release()
        return "break"

    def copy(self):
        """Kopiert den selektierten Text in die Zwischenablage."""
        if not self._has_selection():
            if self._debug:
                log_debug("gui", "Copy called but no selection")
            return
        
        text = self._get_selected_text()
        if not text:
            return
        
        try:
            self.widget.clipboard_clear()
            self.widget.clipboard_append(text)
            if self._debug:
                log_debug("gui", f"Copied {len(text)} chars to clipboard")
        except tk.TclError as e:
            if self._debug:
                log_debug("gui", f"Copy failed: {e}")

    def cut(self):
        """Ausschneiden: Kopieren und Löschen."""
        if not self._has_selection():
            if self._debug:
                log_debug("gui", "Cut called but no selection")
            return
        
        text = self._get_selected_text()
        if not text:
            return
        
        try:
            self.widget.clipboard_clear()
            self.widget.clipboard_append(text)
            
            # Selektierten Bereich löschen
            if self._widget_type == "text":
                self.widget.delete(tk.SEL_FIRST, tk.SEL_LAST)
            else:  # entry
                start = self.widget.index(tk.SEL_FIRST)
                end = self.widget.index(tk.SEL_LAST)
                self.widget.delete(start, end)
            
            if self._debug:
                log_debug("gui", f"Cut {len(text)} chars")
        except tk.TclError as e:
            if self._debug:
                log_debug("gui", f"Cut failed: {e}")

    def paste(self):
        """Fügt Text aus der Zwischenablage ein."""
        try:
            clipboard = self.widget.clipboard_get()
            if not clipboard:
                return
            
            if self._widget_type == "text":
                self.widget.insert(tk.INSERT, clipboard)
            else:
                # Bei Entry: falls etwas ausgewählt ist, überschreiben
                if self._has_selection():
                    start = self.widget.index(tk.SEL_FIRST)
                    end = self.widget.index(tk.SEL_LAST)
                    self.widget.delete(start, end)
                self.widget.insert(tk.INSERT, clipboard)
            
            if self._debug:
                log_debug("gui", f"Pasted {len(clipboard)} chars")
        except tk.TclError as e:
            if self._debug:
                log_debug("gui", f"Paste failed: {e}")

    def select_all(self):
        """Markiert den gesamten Text im Widget."""
        try:
            if self._widget_type == "text":
                self.widget.tag_add(tk.SEL, "1.0", tk.END)
                self.widget.mark_set(tk.INSERT, "1.0")
            else:
                self.widget.select_range(0, tk.END)
                self.widget.icursor(tk.END)
            if self._debug:
                log_debug("gui", "Select all executed")
        except tk.TclError as e:
            if self._debug:
                log_debug("gui", f"Select all failed: {e}")

    def clear(self):
        """Löscht den gesamten Inhalt (nur für Text-Widgets)."""
        if self._widget_type != "text":
            return
        try:
            self.widget.delete("1.0", tk.END)
            if self._debug:
                log_debug("gui", "Cleared text widget")
        except tk.TclError as e:
            if self._debug:
                log_debug("gui", f"Clear failed: {e}")

    def undo(self):
        """Macht die letzte Änderung rückgängig (nur Text)."""
        if self._widget_type != "text":
            return
        try:
            self.widget.edit_undo()
            if self._debug:
                log_debug("gui", "Undo executed")
        except tk.TclError as e:
            if self._debug:
                log_debug("gui", f"Undo failed: {e}")

    def redo(self):
        """Stellt die letzte rückgängig gemachte Änderung wieder her (nur Text)."""
        if self._widget_type != "text":
            return
        try:
            self.widget.edit_redo()
            if self._debug:
                log_debug("gui", "Redo executed")
        except tk.TclError as e:
            if self._debug:
                log_debug("gui", f"Redo failed: {e}")


