class TTSManager:
    """
    Hochwertige Text-to-Speech Verwaltung mit mehreren Engines und Audio-Playern.

    Unterstützte Engines:
        - Piper (primär, hohe Qualität, offline)
        - pyttsx3 (systemeigene Engine, Fallback)
        - espeak (leichtgewichtig, Fallback)

    Features:
        - Automatische Audio-Player-Erkennung (aplay, paplay, ffplay, sox)
        - Intelligenter Fallback bei fehlgeschlagenem Player
        - Lautstärkeregelung (0.0 - 1.0) mit numpy oder struct-Fallback
        - Satzweise Aufteilung langer Texte (max. 500 Zeichen pro Chunk)
        - Asynchrone, nicht-blockierende Ausführung
        - Warteschlange für sequenzielle Wiedergabe (Auto-TTS)
        - Detaillierte Debug-Ausgaben bei --debug=tts oder --debug=3
        - Diagnose unvollständiger Wiedergabe (Byte-Zählung, Zeitvergleich, Queue-Logging)
        - Automatischer Download fehlender Piper-Konfigurationsdateien (.onnx.json)
        - Reparatur beschädigter Modelldateien (Löschen und erneuter Download)
        - Fallback auf medium-Modell bei defektem high-Modell (mit Rekursionsschutz)
        - Test-Audio-Funktion (speaker-test oder TTS)
        - Robuste Fehlerbehandlung mit vollständiger stderr-Protokollierung
        - Sicherer Shutdown ohne Queue-Worker-Abstürze
        - Dynamische Erkennung installierter Piper-Stimmen (für GUI)
        - Textbereinigung: Entfernung von Markup-Zeichen (*, **, _, __)
        - Textnormalisierung: Konvertierung von Zahlen und Abkürzungen
        - Wiederholungslogik bei fehlgeschlagener Piper-Synthese
        - Erweiterte Piper-Debug-Ausgabe bei Wiederholungen
    """

    # -------------------------------------------------------------------------
    # Konstanten
    # -------------------------------------------------------------------------
    MAX_CHUNK_LEN = 500                     # Maximale Textlänge pro Chunk
    PIPER_SAMPLE_RATE = 22050               # Piper gibt 22050 Hz aus
    PIPER_CHANNELS = 1                      # Mono
    PIPER_BYTES_PER_SECOND = PIPER_SAMPLE_RATE * 2  # 16-bit = 2 Bytes pro Sample
    MAX_FALLBACK_DEPTH = 2                  # Maximale Rekursionstiefe für Fallbacks
    MAX_SYNTHESIS_RETRIES = 2               # Wiederholungen bei fehlgeschlagener Synthese

    # Muster für Textbereinigung (Markup)
    _MARKUP_PATTERNS = [
        (re.compile(r'\*\*(.+?)\*\*'), r'\1'),      # **fett** -> fett
        (re.compile(r'\*(.+?)\*'), r'\1'),          # *kursiv* -> kursiv
        (re.compile(r'__(.+?)__'), r'\1'),          # __unterstrichen__ -> unterstrichen
        (re.compile(r'_(.+?)_'), r'\1'),            # _kursiv_ -> kursiv
        (re.compile(r'`(.+?)`'), r'\1'),            # `code` -> code
        (re.compile(r'~~(.+?)~~'), r'\1'),          # ~~durchgestrichen~~ -> durchgestrichen
    ]

    # Abkürzungen für Textnormalisierung (Deutsch/Englisch)
    _ABBREVIATIONS = {
        r'\bDr\.': 'Doktor',
        r'\bMr\.': 'Mister',
        r'\bMrs\.': 'Misses',
        r'\bMs\.': 'Miss',
        r'\bProf\.': 'Professor',
        r'\betc\.': 'et cetera',
        r'\be\.g\.': 'for example',
        r'\bi\.e\.': 'that is',
        r'\bvs\.': 'versus',
        r'\bca\.': 'circa',
        r'\bNo\.': 'Nummer',
        r'\bBd\.': 'Band',
        r'\bJr\.': 'Junior',
        r'\bSr\.': 'Senior',
    }

    # Audio-Player in absteigender Priorität (aplay ist am zuverlässigsten)
    _PLAYER_PRIORITY = [
        ("aplay", ["aplay", "-r", "22050", "-f", "S16_LE", "-t", "raw", "--buffer-size=65536"]),
        ("paplay", ["paplay", "--raw", "/dev/stdin"]),
        ("ffplay", ["ffplay", "-autoexit", "-nodisp", "-f", "s16le", "-ar", "22050", "-ac", "1", "-i", "pipe:0"]),
        ("sox", ["play", "-t", "raw", "-r", "22050", "-e", "signed", "-b", "16", "-c", "1", "-"]),
    ]

    # -------------------------------------------------------------------------
    # Initialisierung
    # -------------------------------------------------------------------------
    def __init__(self, settings: "AdvancedSettings") -> None:
        """
        Initialisiert den TTS-Manager mit den gegebenen Einstellungen.

        Args:
            settings: Erweiterte Einstellungen (enthält TTS-Parameter).
        """
        self.settings = settings
        self._process: Optional[subprocess.Popen] = None
        self._speaking_thread: Optional[threading.Thread] = None
        self._forward_thread: Optional[threading.Thread] = None
        self._forward_stop = threading.Event()
        self._stop_requested = threading.Event()
        self._lock = threading.RLock()

        # TTS-Parameter aus Einstellungen
        self._voice = getattr(settings, "tts_voice", "de_DE-thorsten-medium")
        self._length_scale = getattr(settings, "tts_length_scale", 0.9)
        self._sentence_silence = getattr(settings, "tts_sentence_silence", 0.1)
        self._volume = getattr(settings, "tts_volume", 1.0)
        self._engine_name = getattr(settings, "tts_engine", "piper")

        # Optionen für Textbereinigung und Normalisierung
        self._clean_markup = getattr(settings, "tts_clean_markup", True)
        self._normalize_text = getattr(settings, "tts_normalize_text", True)

        # Verfügbare Player und Engines erkennen
        self._available_players = self._detect_audio_players()
        self._available_engines = self._detect_engines()

        # Queue für sequenzielle Wiedergabe (Auto-TTS)
        self._queue = queue.Queue(maxsize=4)
        self._queue_stop = threading.Event()
        self._queue_worker = threading.Thread(
            target=self._queue_worker_loop, daemon=True, name="TTSQueue"
        )
        self._queue_worker.start()

        # Diagnose: Zähler für verworfene Queue-Einträge
        self._queue_discarded_count = 0

        self._log_initialization()

    def _log_initialization(self) -> None:
        """Protokolliert den Initialisierungszustand."""
        if not self._available_players:
            logger.warning("⚠️ Kein Audio-Player gefunden – TTS wird nicht funktionieren.")
        else:
            log_debug("tts", f"Available audio players: {[p[0] for p in self._available_players]}")
        log_debug("tts", f"Available TTS engines: {self._available_engines}")
        log_debug(
            "tts",
            f"TTSManager initialized: engine={self._engine_name}, voice={self._voice}, "
            f"length_scale={self._length_scale}, sentence_silence={self._sentence_silence}, "
            f"volume={self._volume}, clean_markup={self._clean_markup}, "
            f"normalize_text={self._normalize_text}"
        )

    # -------------------------------------------------------------------------
    # Engine- und Player-Erkennung
    # -------------------------------------------------------------------------
    def _detect_audio_players(self) -> List[Tuple[str, List[str]]]:
        """
        Ermittelt verfügbare Audio-Player auf dem System.

        Returns:
            Liste von (name, command)-Tupeln in Prioritätsreihenfolge.
        """
        players = []
        is_unix = sys.platform.startswith("linux") or sys.platform == "darwin"
        has_display = bool(os.environ.get("DISPLAY")) if is_unix else True

        for name, cmd in self._PLAYER_PRIORITY:
            executable = cmd[0]
            if name == "ffplay" and is_unix and not has_display:
                continue
            if shutil.which(executable):
                players.append((name, cmd))
        return players

    def _detect_engines(self) -> List[str]:
        """Ermittelt verfügbare TTS-Engines."""
        engines = []
        if shutil.which("piper") and self._available_players:
            engines.append("piper")
        if importlib.util.find_spec("pyttsx3") is not None:
            engines.append("pyttsx3")
        if shutil.which("espeak"):
            engines.append("espeak")
        return engines

    # -------------------------------------------------------------------------
    # Öffentliche Konfigurationsmethoden
    # -------------------------------------------------------------------------
    def set_engine(self, engine_name: str) -> None:
        """Setzt die zu verwendende TTS-Engine."""
        if engine_name in self._available_engines:
            self._engine_name = engine_name
            if hasattr(self.settings, "tts_engine"):
                self.settings.tts_engine = engine_name
            logger.info(f"TTS-Engine auf {engine_name} gesetzt")
        else:
            logger.warning(f"TTS-Engine {engine_name} nicht verfügbar")

    def set_voice(self, voice_name: str) -> None:
        """Setzt die Piper-Stimme (nur für Piper)."""
        valid, err_msg = self._validate_piper_model(voice_name, attempt_repair=False)
        if not valid:
            logger.error(f"Piper-Modell ungültig: {err_msg}")
            return
        self._voice = voice_name
        if hasattr(self.settings, "tts_voice"):
            self.settings.tts_voice = voice_name
        log_debug("tts", f"Voice set to {voice_name}")

    def set_volume(self, volume: float) -> None:
        """Setzt die Lautstärke (0.0 - 1.0)."""
        self._volume = max(0.0, min(1.0, volume))
        log_debug("tts", f"Volume set to {self._volume}")

    @property
    def length_scale(self) -> float:
        return self._length_scale

    @length_scale.setter
    def length_scale(self, value: float) -> None:
        self._length_scale = max(0.5, min(1.5, value))

    @property
    def sentence_silence(self) -> float:
        return self._sentence_silence

    @sentence_silence.setter
    def sentence_silence(self, value: float) -> None:
        self._sentence_silence = max(0.0, min(0.5, value))

    def get_available_players(self) -> List[str]:
        """Gibt die Namen der verfügbaren Audio-Player zurück."""
        return [p[0] for p in self._available_players]

    def get_available_engines(self) -> List[str]:
        """Gibt die Namen der verfügbaren TTS-Engines zurück."""
        return self._available_engines.copy()

    def is_available(self, engine: Optional[str] = None) -> bool:
        """Prüft, ob eine bestimmte (oder die aktuelle) Engine verfügbar ist."""
        if engine is None:
            engine = self._engine_name
        if engine == "piper":
            return shutil.which("piper") is not None and bool(self._available_players)
        elif engine == "pyttsx3":
            return importlib.util.find_spec("pyttsx3") is not None
        elif engine == "espeak":
            return shutil.which("espeak") is not None
        return False

    def test_audio(self, callback: Optional[Callable[[bool, str], None]] = None) -> None:
        """Spielt einen kurzen Testton ab (speaker-test oder TTS)."""
        if shutil.which("speaker-test"):
            try:
                subprocess.run(
                    ["speaker-test", "-t", "sine", "-f", "1000", "-l", "1"],
                    timeout=2, check=False
                )
                if callback:
                    callback(True, "Testton erfolgreich abgespielt")
                log_debug("tts", "Test audio played via speaker-test")
                return
            except Exception as e:
                logger.debug(f"speaker-test fehlgeschlagen: {e}")
        self.speak("Test. Dies ist ein kurzer Testton.", callback)

    # -------------------------------------------------------------------------
    # Textbereinigung und Normalisierung
    # -------------------------------------------------------------------------
    def _clean_text(self, text: str) -> str:
        """
        Bereinigt den Text von Markup-Zeichen und normalisiert ihn für TTS.
        """
        if not text:
            return text

        # 1. Markup-Zeichen entfernen
        if self._clean_markup:
            for pattern, replacement in self._MARKUP_PATTERNS:
                text = pattern.sub(replacement, text)
            # Verbleibende einzelne * oder _ entfernen
            text = text.replace('*', '').replace('_', '')

        # 2. Text normalisieren (Abkürzungen, Zahlen)
        if self._normalize_text:
            # Abkürzungen ersetzen
            for pattern, replacement in self._ABBREVIATIONS.items():
                text = re.sub(pattern, replacement, text, flags=re.IGNORECASE)

            # Einfache Zahlenkonvertierung (0-20)
            number_map = {
                '0': 'null', '1': 'eins', '2': 'zwei', '3': 'drei', '4': 'vier',
                '5': 'fünf', '6': 'sechs', '7': 'sieben', '8': 'acht', '9': 'neun',
                '10': 'zehn', '11': 'elf', '12': 'zwölf', '13': 'dreizehn',
                '14': 'vierzehn', '15': 'fünfzehn', '16': 'sechzehn',
                '17': 'siebzehn', '18': 'achtzehn', '19': 'neunzehn', '20': 'zwanzig',
            }
            def replace_number(match):
                num = match.group(0)
                return number_map.get(num, num)
            text = re.sub(r'\b([0-9]|1[0-9]|20)\b', replace_number, text)

        # 3. Mehrfache Leerzeichen und Zeilenumbrüche normalisieren
        text = re.sub(r'\s+', ' ', text).strip()

        return text

    # -------------------------------------------------------------------------
    # Hauptschnittstelle: speak und speak_to_file
    # -------------------------------------------------------------------------
    def speak(self, text: str, callback: Optional[Callable[[bool, str], None]] = None) -> None:
        """
        Gibt den Text als Sprache aus (asynchron).

        Args:
            text: Der vorzulesende Text.
            callback: Wird nach Abschluss mit (erfolg, nachricht) aufgerufen.
        """
        if not text or not text.strip():
            if callback:
                callback(False, "Leerer Text")
            return

        # Text bereinigen vor der Verarbeitung
        original_text = text
        text = self._clean_text(text)
        if text != original_text and (DEBUG_LEVEL >= 3 or 'tts' in DEBUG_COMPONENTS):
            log_debug("tts", f"Text bereinigt: '{original_text[:50]}...' -> '{text[:50]}...'")

        engine = self._engine_name
        if not self.is_available(engine):
            fallback = self._fallback_engine()
            if fallback is None:
                if callback:
                    callback(False, "Keine TTS-Engine verfügbar")
                return
            engine = fallback
            logger.warning(f"Fallback auf Engine '{engine}'")

        self.stop()
        self._stop_requested.clear()

        self._speaking_thread = threading.Thread(
            target=self._speak_blocking,
            args=(text, callback, engine),
            daemon=True,
            name=f"TTS-{engine}",
        )
        self._speaking_thread.start()

    def speak_to_file(
        self, text: str, output_path: str, callback: Optional[Callable[[bool, str], None]] = None
    ) -> None:
        """
        Erzeugt eine Audiodatei aus dem Text (asynchron).

        Args:
            text: Der zu sprechende Text.
            output_path: Zielpfad (endet mit .mp3 oder .wav).
            callback: Wird nach Abschluss mit (erfolg, nachricht) aufgerufen.
        """
        if not text or not text.strip():
            if callback:
                callback(False, "Leerer Text")
            return

        file_ext = os.path.splitext(output_path)[1].lower()
        if file_ext not in (".mp3", ".wav"):
            if callback:
                callback(False, "Nur .mp3 oder .wav werden unterstützt")
            return

        # Text bereinigen
        text = self._clean_text(text)

        engine = self._engine_name
        if not self.is_available(engine):
            fallback = self._fallback_engine()
            if fallback is None:
                if callback:
                    callback(False, "Keine TTS-Engine verfügbar")
                return
            engine = fallback

        self.stop()

        threading.Thread(
            target=self._speak_to_file_blocking,
            args=(text, output_path, callback, engine),
            daemon=True,
            name=f"TTS-File-{engine}",
        ).start()

    def speak_queued(self, text: str, callback: Optional[Callable[[bool, str], None]] = None) -> None:
        """
        Fügt Text in die Warteschlange ein. Ältere Texte werden verworfen (max. 1).
        """
        if not text or not text.strip():
            if callback:
                callback(False, "Leerer Text")
            return
        try:
            self._queue.put_nowait((text, callback))
        except queue.Full:
            try:
                old = self._queue.get_nowait()
                self._queue_discarded_count += 1
                if DEBUG_LEVEL >= 3 or 'tts' in DEBUG_COMPONENTS:
                    log_debug("tts", f"Queue voll – älteren Text verworfen (#{self._queue_discarded_count}): {old[0][:50]}...")
                self._queue.put_nowait((text, callback))
            except queue.Empty:
                pass

    def stop(self) -> None:
        """
        Stoppt die laufende Sprachausgabe sofort und zuverlässig.
        """
        log_debug("tts", "TTSManager.stop() called")

        with self._lock:
            self._stop_requested.set()
            if self._process and self._process.poll() is None:
                log_debug("tts", f"  → Terminating Piper process (PID {self._process.pid})...")
                try:
                    PlatformUtils.terminate_process(
                        self._process,
                        child_terminate_timeout=1.0,
                        child_kill_wait=0.5,
                        parent_terminate_timeout=2.0,
                        parent_kill_wait=1.0,
                        fallback_terminate_timeout=1.0,
                        fallback_kill_wait=0.5,
                    )
                    log_debug("tts", "  → Piper process terminated")
                except Exception as e:
                    logger.warning(f"Fehler beim Terminieren des Piper-Prozesses: {e}")
                finally:
                    self._process = None
            else:
                log_debug("tts", "  → No active Piper process to stop")

        if self._forward_stop:
            self._forward_stop.set()
        if self._forward_thread and self._forward_thread.is_alive():
            log_debug("tts", "  → Joining forward thread...")
            self._forward_thread.join(timeout=1.0)
            if self._forward_thread.is_alive():
                logger.warning("Forward thread did not terminate within timeout")
                try:
                    self._forward_thread.daemon = True
                except RuntimeError:
                    pass
            else:
                log_debug("tts", "  → Forward thread joined")
        self._forward_thread = None

        # Warteschlange leeren
        cleared = 0
        try:
            while True:
                self._queue.get_nowait()
                cleared += 1
        except queue.Empty:
            pass
        if cleared > 0:
            log_debug("tts", f"  → Cleared {cleared} items from TTS queue")

        try:
            self._queue.put_nowait(None)
        except queue.Full:
            pass

        log_debug("tts", "TTSManager.stop() completed")

    # -------------------------------------------------------------------------
    # Blockierende Ausführung (wird in Threads ausgeführt)
    # -------------------------------------------------------------------------
    def _speak_blocking(self, text: str, callback: Optional[Callable], engine: str) -> None:
        """Führt die TTS-Ausgabe synchron im aktuellen Thread aus."""
        if text is None:
            if callback:
                callback(False, "Abgebrochen")
            return

        chunks = self._split_text(text)
        if not chunks:
            if callback:
                callback(False, "Kein Text zum Abspielen")
            return

        if len(chunks) > 1 and (DEBUG_LEVEL >= 3 or 'tts' in DEBUG_COMPONENTS):
            log_debug("tts", f"Text aufgeteilt in {len(chunks)} Chunks (Längen: {[len(c) for c in chunks]})")

        for i, chunk in enumerate(chunks):
            if self._stop_requested.is_set():
                if callback:
                    callback(False, "Abgebrochen")
                return

            log_debug("tts", f"Spiele Chunk {i+1}/{len(chunks)} ({len(chunk)} Zeichen)")
            success, message = self._speak_chunk(chunk, engine)

            if not success:
                if callback:
                    callback(False, message)
                return

        if callback:
            callback(True, "Alle Chunks abgespielt")

    def _speak_to_file_blocking(
        self, text: str, output_path: str, callback: Optional[Callable], engine: str
    ) -> None:
        """Erzeugt eine Audiodatei synchron."""
        if text is None:
            if callback:
                callback(False, "Abgebrochen")
            return

        if engine == "piper":
            success, message = self._speak_to_file_piper(text, output_path)
        elif engine == "pyttsx3":
            success, message = self._speak_to_file_pyttsx3(text, output_path)
        elif engine == "espeak":
            success, message = self._speak_to_file_espeak(text, output_path)
        else:
            success, message = False, f"Unbekannte Engine: {engine}"

        if callback:
            callback(success, message)

    def _speak_chunk(self, text: str, engine: str) -> Tuple[bool, str]:
        """Spricht einen einzelnen Chunk mit der angegebenen Engine."""
        if engine == "piper":
            return self._speak_piper_sync(text)
        elif engine == "pyttsx3":
            return self._speak_pyttsx3_sync(text)
        elif engine == "espeak":
            return self._speak_espeak_sync(text)
        else:
            return False, f"Unbekannte Engine: {engine}"

    # -------------------------------------------------------------------------
    # Piper-Implementierung (primär)
    # -------------------------------------------------------------------------
    def _get_piper_cache_dir(self) -> str:
        """Ermittelt das plattformunabhängige Cache-Verzeichnis für Piper-Modelle."""
        if IS_WINDOWS:
            base = os.environ.get("APPDATA", os.path.expanduser("~\\AppData\\Roaming"))
            return os.path.join(base, "piper")
        base = os.environ.get("XDG_CACHE_HOME", os.path.expanduser("~/.cache"))
        return os.path.join(base, "piper")

    def _validate_piper_model(self, voice_name: str, attempt_repair: bool = True) -> Tuple[bool, str]:
        """
        Prüft, ob die Piper-Modelldateien existieren und gültig sind.
        Bei leerer Datei wird versucht, sie zu löschen und die JSON neu herunterzuladen.
        """
        cache_dir = self._get_piper_cache_dir()
        model_path = os.path.join(cache_dir, f"{voice_name}.onnx")
        json_path = model_path + ".json"

        def check_file(path, desc):
            if not os.path.exists(path):
                return False, f"{desc} nicht gefunden: {path}"
            if os.path.getsize(path) == 0:
                if attempt_repair:
                    logger.warning(f"{desc} ist leer, lösche: {path}")
                    try:
                        os.unlink(path)
                    except Exception as e:
                        logger.error(f"Löschen fehlgeschlagen: {e}")
                return False, f"{desc} ist leer: {path}"
            return True, ""

        ok_model, err_model = check_file(model_path, "Modelldatei")
        ok_json, err_json = check_file(json_path, "Konfigurationsdatei")

        if not ok_model or not ok_json:
            if attempt_repair:
                logger.info(f"Versuche Reparatur für Stimme {voice_name}...")
                if not os.path.exists(json_path):
                    self._download_piper_json(voice_name, cache_dir)
                return self._validate_piper_model(voice_name, attempt_repair=False)
            return False, err_model or err_json
        return True, ""

    def _download_piper_json(self, voice_name: str, cache_dir: str) -> bool:
        """Lädt fehlende .onnx.json-Datei von Hugging Face herunter."""
        parts = voice_name.split('-')
        if len(parts) < 3:
            return False
        lang_full, speaker, quality = parts[0], parts[1], parts[2]
        lang_short = lang_full.split('_')[0]
        filename = f"{voice_name}.onnx.json"
        url = (f"https://huggingface.co/rhasspy/piper-voices/resolve/main/"
               f"{lang_short}/{lang_full}/{speaker}/{quality}/{filename}")

        try:
            import requests
            response = requests.get(url, timeout=30)
            if response.status_code == 200:
                json_path = os.path.join(cache_dir, filename)
                with open(json_path, 'wb') as f:
                    f.write(response.content)
                logger.info(f"✅ Konfigurationsdatei {filename} heruntergeladen")
                return True
            elif response.status_code == 404:
                logger.error(f"Stimme '{voice_name}' existiert nicht auf Hugging Face (404).")
                return False
        except Exception as e:
            logger.error(f"Download fehlgeschlagen: {e}")
        return False

    def _find_piper_executable(self) -> str:
        """Sucht das Piper-Executable (PATH oder venv)."""
        piper_exe = shutil.which("piper")
        if not piper_exe:
            venv_bin = os.path.join(os.path.dirname(sys.executable), "bin", "piper")
            if os.path.exists(venv_bin):
                return venv_bin
        if not piper_exe:
            raise FileNotFoundError("Piper nicht im PATH gefunden")
        return piper_exe

    def _prepare_piper_model(self) -> Tuple[str, str]:
        """Bereitet Modell- und Konfigurationspfade vor, lädt ggf. JSON nach."""
        cache_dir = self._get_piper_cache_dir()
        model_path = os.path.join(cache_dir, f"{self._voice}.onnx")
        json_path = model_path + ".json"

        valid, err_msg = self._validate_piper_model(self._voice)
        if not valid:
            if "Konfigurationsdatei nicht gefunden" in err_msg:
                logger.warning("Konfigurationsdatei fehlt – versuche Download...")
                if self._download_piper_json(self._voice, cache_dir):
                    valid, err_msg = self._validate_piper_model(self._voice)
            if not valid:
                raise FileNotFoundError(err_msg)

        return model_path, json_path

    def _start_audio_player(self) -> subprocess.Popen:
        """Startet den ersten verfügbaren Audio-Player."""
        for player_name, player_cmd in self._available_players:
            log_debug("tts", f"Versuche Audio-Player: {player_name}")
            proc = subprocess.Popen(
                player_cmd,
                stdin=subprocess.PIPE,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.PIPE,
            )
            time.sleep(0.4)
            if proc.poll() is None:
                log_debug("tts", f"Audio-Player {player_name} gestartet (PID: {proc.pid})")
                return proc
            else:
                stderr = proc.stderr.read().decode(errors="ignore")
                logger.debug(f"Audio-Player {player_name} sofort beendet: {stderr[:200]}")
        raise RuntimeError("Kein Audio-Player konnte gestartet werden")

    def _apply_volume_scaling(self, chunk: bytes, _np_available: bool) -> bytes:
        """Skaliert die Lautstärke eines Audio-Chunks."""
        if not chunk or self._volume == 1.0:
            return chunk

        if _np_available:
            import numpy as np
            data = np.frombuffer(chunk, dtype=np.int16).astype(np.float32)
            data *= self._volume
            np.clip(data, -32768, 32767, out=data)
            return data.astype(np.int16).tobytes()
        else:
            import struct
            num_samples = len(chunk) // 2
            fmt = f"<{num_samples}h"
            samples = struct.unpack(fmt, chunk)
            scaled = tuple(int(max(-32768, min(32767, s * self._volume))) for s in samples)
            return struct.pack(fmt, *scaled)

    def _speak_piper_sync(self, text: str, _depth: int = 0, _retry: int = 0) -> Tuple[bool, str]:
        """
        Synchrone Piper-Ausgabe (wird im Worker-Thread aufgerufen).
        Gibt (erfolg, nachricht) zurück.

        Enthält umfangreiche Diagnose, Wiederholungslogik und Schutz gegen
        Ausführung während des Shutdowns (dispose). Der Timeout für den
        Audio-Player wurde auf 15 Sekunden erhöht, um ein vorzeitiges Killen
        zu vermeiden. Bei Bedarf wird erst SIGTERM, dann SIGKILL gesendet.
        """
        # -----------------------------------------------------------------
        # 0. Vorab-Prüfung: Wurde der TTSManager bereits disposed oder gestoppt?
        # -----------------------------------------------------------------
        if getattr(self, "_disposed", False):
            log_debug("tts", "_speak_piper_sync: TTSManager disposed – abort")
            return False, "TTSManager disposed"
        if self._stop_requested.is_set():
            log_debug("tts", "_speak_piper_sync: Stop requested – abort")
            return False, "Stop requested"

        if _depth >= self.MAX_FALLBACK_DEPTH:
            return False, f"Maximale Fallback-Tiefe ({self.MAX_FALLBACK_DEPTH}) erreicht"
        if _retry >= self.MAX_SYNTHESIS_RETRIES:
            return False, f"Maximale Wiederholungen ({self.MAX_SYNTHESIS_RETRIES}) erreicht"

        process = None
        audio_player = None
        forwarded_bytes = 0
        total_piper_bytes = 0
        _np_available = NUMPY_AVAILABLE
        original_voice = self._voice

        try:
            # --- Modell vorbereiten (mit Fallback high -> medium) ---
            try:
                model_path, json_path = self._prepare_piper_model()
            except FileNotFoundError as e:
                if getattr(self, "_disposed", False) or self._stop_requested.is_set():
                    return False, "Aborted during model preparation"
                if self._voice.endswith("-high"):
                    fallback_voice = self._voice.replace("-high", "-medium")
                    logger.warning(f"Piper high-Modell fehlerhaft, versuche Fallback auf {fallback_voice}")
                    self._voice = fallback_voice
                    return self._speak_piper_sync(text, _depth + 1, _retry)
                else:
                    return False, str(e)

            # --- Erneute Prüfung nach Modell-Vorbereitung ---
            if getattr(self, "_disposed", False) or self._stop_requested.is_set():
                return False, "Aborted before starting Piper"

            # --- Piper starten ---
            piper_exe = self._find_piper_executable()
            cmd = [
                piper_exe, "--model", model_path,
                "--length_scale", str(self._length_scale),
                "--sentence_silence", str(self._sentence_silence),
                "--output-raw",
            ]
            if _retry > 0:
                cmd.append("--debug")

            if DEBUG_LEVEL >= 3 or 'tts' in DEBUG_COMPONENTS:
                log_debug("tts", f"Starte Piper (retry={_retry}): {' '.join(cmd)}")
            process = subprocess.Popen(
                cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE
            )
            with self._lock:
                # Prüfen, ob während Popen disposed wurde
                if getattr(self, "_disposed", False):
                    process.kill()
                    return False, "Disposed during process start"
                self._process = process

            # --- Audio-Player starten ---
            audio_player = self._start_audio_player()
            player_start_time = time.perf_counter()

            # --- Text an Piper senden (mit Flush) ---
            try:
                process.stdin.write(text.encode("utf-8"))
                process.stdin.flush()
            except BrokenPipeError:
                stderr = process.stderr.read().decode(errors="ignore")
                process.wait(timeout=2.0)
                if getattr(self, "_disposed", False) or self._stop_requested.is_set():
                    return False, "Aborted"
                if _retry < self.MAX_SYNTHESIS_RETRIES:
                    logger.warning(f"Piper stdin BrokenPipe, versuche erneut ({_retry+1}/{self.MAX_SYNTHESIS_RETRIES})")
                    return self._speak_piper_sync(text, _depth, _retry + 1)
                return False, f"Piper schloss stdin frühzeitig (exit {process.returncode}):\n{stderr}"
            finally:
                try:
                    process.stdin.close()
                except BrokenPipeError:
                    pass

            # --- Forward-Thread für Datenweitergabe ---
            self._forward_stop.clear()
            forward_error = None
            forward_done = threading.Event()

            def forward():
                nonlocal forwarded_bytes, forward_error, total_piper_bytes
                try:
                    start_time = time.time()
                    while not self._forward_stop.is_set():
                        chunk = process.stdout.read(8192)
                        if not chunk:
                            break
                        total_piper_bytes += len(chunk)
                        if forwarded_bytes == 0 and time.time() - start_time > 3.0:
                            forward_error = TimeoutError("Piper liefert keine Audiodaten")
                            break

                        chunk = self._apply_volume_scaling(chunk, _np_available)
                        try:
                            audio_player.stdin.write(chunk)
                            audio_player.stdin.flush()
                            forwarded_bytes += len(chunk)
                        except BrokenPipeError:
                            logger.warning("Audio-Player-Pipe unterbrochen")
                            forward_error = BrokenPipeError("Audio player pipe closed early")
                            break
                except Exception as e:
                    forward_error = e
                    logger.error(f"Fehler in forward-Thread: {e}", exc_info=True)
                finally:
                    try:
                        audio_player.stdin.close()
                    except Exception:
                        pass
                    forward_done.set()

            self._forward_thread = threading.Thread(target=forward, daemon=True, name="TTS-Forward")
            self._forward_thread.start()

            # --- Auf Piper warten ---
            try:
                process.wait(timeout=120)
            except subprocess.TimeoutExpired:
                process.kill()
                process.wait()
                if getattr(self, "_disposed", False):
                    return False, "Disposed"
                return False, "Piper timeout nach 120 Sekunden"

            # --- Forward beenden ---
            self._forward_stop.set()
            forward_done.wait(timeout=2.0)
            if self._forward_thread and self._forward_thread.is_alive():
                self._forward_thread.join(timeout=2.0)
            self._forward_thread = None

            # --- Auf Audio-Player warten (mit gestaffelter Terminierung) ---
            time.sleep(0.2)
            try:
                audio_player.stdin.close()
            except Exception:
                pass
            try:
                # Erhöhter Timeout: 15 Sekunden statt 5
                audio_player.wait(timeout=15.0)
            except subprocess.TimeoutExpired:
                logger.warning("Audio-Player beendet sich nicht, sende SIGTERM")
                audio_player.terminate()
                try:
                    audio_player.wait(timeout=2.0)
                except subprocess.TimeoutExpired:
                    logger.warning("Audio-Player reagiert nicht auf SIGTERM, sende SIGKILL")
                    audio_player.kill()
                    audio_player.wait(timeout=1.0)

            player_duration = time.perf_counter() - player_start_time
            expected_duration = forwarded_bytes / self.PIPER_BYTES_PER_SECOND

            # --- Detaillierte Debug-Ausgaben ---
            if DEBUG_LEVEL >= 3 or 'tts' in DEBUG_COMPONENTS:
                log_debug("tts", f"Piper bytes read: {total_piper_bytes}, forwarded: {forwarded_bytes}")
                if total_piper_bytes != forwarded_bytes:
                    log_debug("tts", f"WARNUNG: Nicht alle Bytes wurden weitergeleitet! "
                              f"Diff: {total_piper_bytes - forwarded_bytes} bytes")
                if forward_error:
                    log_debug("tts", f"Forward-Fehler: {forward_error}")
                log_debug("tts", f"Player lief {player_duration:.2f}s, erwartete Dauer {expected_duration:.2f}s")
                if player_duration < expected_duration * 0.9:
                    log_debug("tts", f"WARNUNG: Audio-Player endete {expected_duration - player_duration:.2f}s zu früh!")
                stderr = process.stderr.read().decode(errors="ignore")
                if stderr:
                    log_debug("tts", f"Piper stderr: {stderr[:500]}")
                if audio_player.stderr:
                    aplay_stderr = audio_player.stderr.read().decode(errors="ignore")
                    if aplay_stderr:
                        log_debug("tts", f"aplay stderr: {aplay_stderr.strip()}")

            # --- Fehlerauswertung ---
            # Vor jeder weiteren Aktion prüfen, ob disposed wurde
            if getattr(self, "_disposed", False):
                log_debug("tts", "_speak_piper_sync: disposed during execution – returning without fallback")
                return False, "Disposed"

            if forward_error:
                stderr = process.stderr.read().decode(errors="ignore")
                if _retry < self.MAX_SYNTHESIS_RETRIES and not self._stop_requested.is_set():
                    logger.warning(f"Forward-Fehler, versuche erneut ({_retry+1}/{self.MAX_SYNTHESIS_RETRIES})")
                    return self._speak_piper_sync(text, _depth, _retry + 1)
                return False, f"Forward-Fehler: {forward_error}\nPiper stderr:\n{stderr}"

            if process.returncode != 0 or forwarded_bytes == 0:
                stderr = process.stderr.read().decode(errors="ignore")
                logger.error(f"❌ Piper Fehler (exit {process.returncode}, bytes={forwarded_bytes}):\n{stderr}")

                # Automatische Reparatur bei Protobuf-Fehler
                if "InvalidProtobuf" in stderr or "Protobuf parsing failed" in stderr:
                    model_path = os.path.join(self._get_piper_cache_dir(), f"{self._voice}.onnx")
                    logger.warning(f"Beschädigtes Piper-Modell erkannt, lösche: {model_path}")
                    try:
                        os.unlink(model_path)
                    except Exception as e:
                        logger.error(f"Löschen fehlgeschlagen: {e}")
                    logger.info("Das Modell wurde gelöscht und wird beim nächsten Start neu heruntergeladen.")

                # Fallback auf medium, wenn high fehlschlägt – NUR wenn nicht disposed/stopped
                if self._voice.endswith("-high") and not self._stop_requested.is_set():
                    fallback_voice = self._voice.replace("-high", "-medium")
                    logger.warning(f"Wechsle zu Fallback-Stimme: {fallback_voice}")
                    self._voice = fallback_voice
                    return self._speak_piper_sync(text, _depth + 1, _retry)
                else:
                    if _retry < self.MAX_SYNTHESIS_RETRIES and not self._stop_requested.is_set():
                        logger.warning(f"Piper Fehler, versuche erneut ({_retry+1}/{self.MAX_SYNTHESIS_RETRIES})")
                        return self._speak_piper_sync(text, _depth, _retry + 1)
                    return False, f"Piper exit {process.returncode}, bytes={forwarded_bytes}\n{stderr}"

            logger.info(f"✅ Piper erfolgreich: {forwarded_bytes} Bytes an {self._available_players[0][0]} gesendet")
            return True, ""

        except Exception as e:
            logger.error(f"Unerwarteter Fehler in _speak_piper_sync: {e}", exc_info=True)
            if getattr(self, "_disposed", False) or self._stop_requested.is_set():
                return False, "Aborted due to dispose/stop"
            if _retry < self.MAX_SYNTHESIS_RETRIES:
                logger.warning(f"Unerwarteter Fehler, versuche erneut ({_retry+1}/{self.MAX_SYNTHESIS_RETRIES})")
                return self._speak_piper_sync(text, _depth, _retry + 1)
            return False, str(e)
        finally:
            # Aufräumen
            if process and process.poll() is None:
                process.kill()
            if audio_player and audio_player.poll() is None:
                audio_player.terminate()
            with self._lock:
                if self._process == process:
                    self._process = None
            self._voice = original_voice

    def _speak_to_file_piper(self, text: str, output_path: str) -> Tuple[bool, str]:
        """Erzeugt eine Audiodatei mit Piper."""
        temp_wav = None
        try:
            piper_exe = self._find_piper_executable()
            model_path, _ = self._prepare_piper_model()

            need_conversion = output_path.lower().endswith(".mp3")
            if need_conversion:
                temp_wav = tempfile.NamedTemporaryFile(suffix=".wav", delete=False).name
                out_wav = temp_wav
            else:
                out_wav = output_path

            cmd = [
                piper_exe, "--model", model_path,
                "--length_scale", str(self._length_scale),
                "--sentence_silence", str(self._sentence_silence),
                "--output_file", out_wav,
            ]
            proc = subprocess.run(cmd, input=text, capture_output=True, text=True, timeout=60)
            if proc.returncode != 0:
                return False, f"Piper Fehler: {proc.stderr[:500]}"

            if need_conversion:
                if not shutil.which("ffmpeg"):
                    return False, "ffmpeg nicht gefunden"
                subprocess.run(["ffmpeg", "-i", out_wav, "-y", output_path], check=True, capture_output=True)

            return True, f"Gespeichert unter {output_path}"
        except Exception as e:
            return False, str(e)
        finally:
            if temp_wav and os.path.exists(temp_wav):
                try:
                    os.unlink(temp_wav)
                except Exception:
                    pass

    # -------------------------------------------------------------------------
    # pyttsx3-Implementierung (Fallback)
    # -------------------------------------------------------------------------
    def _speak_pyttsx3_sync(self, text: str) -> Tuple[bool, str]:
        try:
            import pyttsx3
            engine = pyttsx3.init()
            if self._volume != 1.0:
                engine.setProperty("volume", self._volume)
            engine.setProperty("rate", 150)
            voices = engine.getProperty('voices')
            if voices:
                engine.setProperty('voice', voices[0].id)
            engine.say(text)
            engine.runAndWait()
            return True, ""
        except Exception as e:
            return False, str(e)

    def _speak_to_file_pyttsx3(self, text: str, output_path: str) -> Tuple[bool, str]:
        temp_wav = None
        try:
            import pyttsx3
            engine = pyttsx3.init()
            if self._volume != 1.0:
                engine.setProperty("volume", self._volume)
            engine.setProperty("rate", 150)
            voices = engine.getProperty('voices')
            if voices:
                engine.setProperty('voice', voices[0].id)
            temp_wav = tempfile.NamedTemporaryFile(suffix=".wav", delete=False).name
            engine.save_to_file(text, temp_wav)
            engine.runAndWait()

            if output_path.lower().endswith(".mp3"):
                if not shutil.which("ffmpeg"):
                    return False, "ffmpeg nicht gefunden"
                subprocess.run(["ffmpeg", "-i", temp_wav, "-y", output_path], check=True)
            else:
                shutil.copy2(temp_wav, output_path)
            return True, f"Gespeichert unter {output_path}"
        except Exception as e:
            return False, str(e)
        finally:
            if temp_wav and os.path.exists(temp_wav):
                os.unlink(temp_wav)

    # -------------------------------------------------------------------------
    # espeak-Implementierung (leichtgewichtig)
    # -------------------------------------------------------------------------
    def _speak_espeak_sync(self, text: str) -> Tuple[bool, str]:
        try:
            lang_code = getattr(self.settings, "target_language", "de")
            espeak_lang = {"de": "de", "en": "en", "fr": "fr", "es": "es"}.get(lang_code, "de")
            cmd = ["espeak", "-v", espeak_lang, "-p", "50", "-s", "150"]
            if self._volume != 1.0:
                cmd.extend(["-a", str(int(100 * self._volume))])
            subprocess.run(cmd, input=text, timeout=30, check=True)
            return True, ""
        except Exception as e:
            return False, str(e)

    def _speak_to_file_espeak(self, text: str, output_path: str) -> Tuple[bool, str]:
        temp_wav = None
        try:
            lang_code = getattr(self.settings, "target_language", "de")
            espeak_lang = {"de": "de", "en": "en", "fr": "fr", "es": "es"}.get(lang_code, "de")
            temp_wav = tempfile.NamedTemporaryFile(suffix=".wav", delete=False).name
            cmd = ["espeak", "-v", espeak_lang, "-w", temp_wav, "-p", "50", "-s", "150"]
            if self._volume != 1.0:
                cmd.extend(["-a", str(int(100 * self._volume))])
            subprocess.run(cmd, input=text, timeout=30, check=True)

            if output_path.lower().endswith(".mp3"):
                if not shutil.which("ffmpeg"):
                    return False, "ffmpeg nicht gefunden"
                subprocess.run(["ffmpeg", "-i", temp_wav, "-y", output_path], check=True)
            else:
                shutil.copy2(temp_wav, output_path)
            return True, f"Gespeichert unter {output_path}"
        except Exception as e:
            return False, str(e)
        finally:
            if temp_wav and os.path.exists(temp_wav):
                os.unlink(temp_wav)

    # -------------------------------------------------------------------------
    # Hilfsmethoden
    # -------------------------------------------------------------------------
    def _split_text(self, text: str) -> List[str]:
        """Teilt einen langen Text in sinnvolle Chunks auf."""
        if text is None:
            return []
        if len(text) <= self.MAX_CHUNK_LEN:
            return [text]

        sentences = re.split(r"(?<=[.!?])\s+", text)
        chunks = []
        current = ""
        for sent in sentences:
            if len(sent) > self.MAX_CHUNK_LEN:
                words = sent.split()
                for w in words:
                    if len(current) + len(w) + 1 <= self.MAX_CHUNK_LEN:
                        current = (current + " " + w) if current else w
                    else:
                        if current:
                            chunks.append(current)
                        current = w
            else:
                if len(current) + len(sent) + 1 <= self.MAX_CHUNK_LEN:
                    current = (current + " " + sent) if current else sent
                else:
                    if current:
                        chunks.append(current)
                    current = sent
        if current:
            chunks.append(current)
        return chunks

    def _fallback_engine(self) -> Optional[str]:
        """Gibt die erste verfügbare Engine zurück."""
        for eng in ["piper", "pyttsx3", "espeak"]:
            if self.is_available(eng):
                return eng
        return None

    def _queue_worker_loop(self) -> None:
        """
        Arbeitet die TTS-Warteschlange sequenziell ab.

        Verbesserungen:
            - Kurzer Timeout (0,1 s) für reaktionsschnellen Shutdown.
            - Explizite Prüfung auf _queue_stop vor jedem get().
            - Sentinel (None) beendet die Schleife sofort.
            - Robuste Fehlerbehandlung – einzelne fehlgeschlagene Ausgaben
              unterbrechen die Queue nicht.
            - Debug-Ausgaben bei --debug=tts oder --debug=3.
            - Prüfung auf _disposed und _stop_requested vor der Wiedergabe.
        """
        log_debug("tts", "TTSQueue worker thread started")

        while not self._queue_stop.is_set():
            # Vor dem blockierenden get prüfen, ob Stop gesetzt ist
            if self._queue_stop.is_set():
                break

            try:
                item = self._queue.get(timeout=0.1)
            except queue.Empty:
                continue

            # Sentinel behandeln
            if item is None:
                log_debug("tts", "TTSQueue received sentinel – exiting")
                self._queue.task_done()
                break

            # Item muss ein Tupel (text, callback) sein
            if not isinstance(item, tuple) or len(item) < 1:
                log_debug("tts", f"Ungültiges Queue-Item ignoriert: {type(item)}")
                self._queue.task_done()
                continue

            text, callback = item
            if not text or not text.strip():
                log_debug("tts", "Leerer Text in Queue – ignoriert")
                if callback:
                    try:
                        callback(False, "Leerer Text")
                    except Exception:
                        pass
                self._queue.task_done()
                continue

            # Vor der Wiedergabe prüfen, ob der Manager disposed oder gestoppt wurde
            if getattr(self, "_disposed", False) or self._stop_requested.is_set():
                log_debug("tts", "TTSManager disposed/stopped – verwerfe Queue-Item")
                if callback:
                    try:
                        callback(False, "Abgebrochen")
                    except Exception:
                        pass
                self._queue.task_done()
                continue

            log_debug("tts", f"TTSQueue: speaking text ({len(text)} chars)")
            try:
                self._speak_blocking(text, callback, self._engine_name)
            except Exception as e:
                logger.error(f"Fehler in _speak_blocking: {e}", exc_info=True)
                if callback:
                    try:
                        callback(False, str(e))
                    except Exception:
                        pass
            finally:
                self._queue.task_done()

        log_debug("tts", "TTSQueue worker thread finished")

    # -------------------------------------------------------------------------
    # Ressourcenfreigabe und dynamische Stimmen-Erkennung
    # -------------------------------------------------------------------------
    def dispose(self) -> None:
        """
        Gibt alle Ressourcen des TTSManagers frei und beendet laufende Prozesse.

        Diese Methode wird beim Herunterfahren der Anwendung aufgerufen. Sie stellt sicher,
        dass:
            - Laufende Sprachausgaben sofort abgebrochen werden.
            - Alle Subprozesse (Piper, Audio‑Player) hart beendet werden.
            - Der Queue‑Worker‑Thread sauber gestoppt wird.
            - Keine Hintergrundprozesse oder Threads zurückbleiben.
            - Keine Fallback-Mechanismen während des Shutdowns ausgelöst werden.

        Die Methode ist idempotent und kann mehrfach aufgerufen werden.
        """
        # Verhindert doppelte Ausführung
        if getattr(self, "_disposed", False):
            log_debug("tts", "TTSManager.dispose() already called, skipping")
            return
        self._disposed = True

        log_debug("tts", "TTSManager.dispose() called – cleaning up resources")

        # -----------------------------------------------------------------
        # 1. Alle Stop-Events setzen, um laufende Threads zu benachrichtigen
        # -----------------------------------------------------------------
        self._stop_requested.set()
        self._forward_stop.set()
        self._queue_stop.set()
        log_debug("tts", "  → Stop events set (stop_requested, forward_stop, queue_stop)")

        # -----------------------------------------------------------------
        # 2. Laufenden Forward-Thread stoppen (falls vorhanden)
        # -----------------------------------------------------------------
        if self._forward_thread and self._forward_thread.is_alive():
            log_debug("tts", "  → Stopping forward thread...")
            self._forward_thread.join(timeout=1.0)
            if self._forward_thread.is_alive():
                logger.warning("Forward thread did not terminate within timeout")
                try:
                    self._forward_thread.daemon = True
                except RuntimeError:
                    pass
            else:
                log_debug("tts", "  → Forward thread joined")
        self._forward_thread = None

        # -----------------------------------------------------------------
        # 3. Laufenden Piper-Prozess **hart** beenden (SIGKILL)
        #    Verwende kill() statt terminate(), um zu verhindern, dass
        #    die aufrufende _speak_piper_sync den Fallback-Mechanismus
        #    (z. B. Wechsel auf medium) auslöst.
        # -----------------------------------------------------------------
        with self._lock:
            proc = self._process
            self._process = None
        if proc and proc.poll() is None:
            log_debug("tts", f"  → Killing Piper process (PID {proc.pid})...")
            try:
                proc.kill()
                proc.wait(timeout=1.0)
                log_debug("tts", "  → Piper process killed")
            except Exception as e:
                logger.warning(f"Error killing Piper: {e}")

        # -----------------------------------------------------------------
        # 4. Queue-Worker sauber beenden
        # -----------------------------------------------------------------
        # Queue leeren und Sentinel senden, um Worker aufzuwecken
        try:
            while True:
                self._queue.get_nowait()
        except queue.Empty:
            pass
        log_debug("tts", "  → Queue emptied")

        try:
            self._queue.put_nowait(None)
        except queue.Full:
            pass

        if self._queue_worker.is_alive():
            log_debug("tts", "  → Joining queue worker thread...")
            self._queue_worker.join(timeout=2.0)
            if self._queue_worker.is_alive():
                logger.warning("Queue worker thread did not terminate within timeout")
                try:
                    self._queue_worker.daemon = True
                except RuntimeError:
                    pass
            else:
                log_debug("tts", "  → Queue worker thread joined")
        self._queue_worker = None

        # -----------------------------------------------------------------
        # 5. Garbage Collection anregen
        # -----------------------------------------------------------------
        gc.collect()
        log_debug("tts", "TTSManager.dispose() completed successfully")

    def get_installed_piper_voices(self) -> List[str]:
        """
        Scannt das Piper-Cache-Verzeichnis und gibt eine Liste aller
        vollständig installierten Stimmen zurück (Model + JSON vorhanden).
        """
        cache_dir = self._get_piper_cache_dir()
        if not os.path.isdir(cache_dir):
            return []
        voices = set()
        for filename in os.listdir(cache_dir):
            if filename.endswith(".onnx"):
                voice_name = filename[:-5]
                model_path = os.path.join(cache_dir, filename)
                json_path = model_path + ".json"
                if os.path.exists(json_path) and os.path.getsize(model_path) > 0:
                    voices.add(voice_name)
        return sorted(voices)


class DarkMessageBox:
    __slots__ = ()

    @classmethod
    def showinfo(
        cls,
        title: str,
        message: str,
        parent: Optional[tk.Tk] = None,
        timeout: Optional[int] = None,
    ) -> Optional[bool]:
        return cls._show_dialog(title, message, "info", parent, timeout=timeout)

    @classmethod
    def showwarning(
        cls,
        title: str,
        message: str,
        parent: Optional[tk.Tk] = None,
        timeout: Optional[int] = None,
    ) -> Optional[bool]:
        return cls._show_dialog(title, message, "warning", parent, timeout=timeout)

    @classmethod
    def showerror(
        cls,
        title: str,
        message: str,
        parent: Optional[tk.Tk] = None,
        timeout: Optional[int] = None,
    ) -> Optional[bool]:
        return cls._show_dialog(title, message, "error", parent, timeout=timeout)

    @classmethod
    def askokcancel(
        cls,
        title: str,
        message: str,
        parent: Optional[tk.Tk] = None,
        timeout: Optional[int] = None,
    ) -> Optional[bool]:
        return cls._show_dialog(
            title, message, "question", parent, buttons=True, timeout=timeout
        )

    @classmethod
    def askyesno(
        cls,
        title: str,
        message: str,
        parent: Optional[tk.Tk] = None,
        timeout: Optional[int] = None,
    ) -> Optional[bool]:
        return cls._ask_yesno(title, message, parent, timeout=timeout)

    @classmethod
    def show_progress(
        cls,
        title: str,
        message: str,
        parent: Optional[tk.Tk] = None,
        indeterminate: bool = True,
    ) -> Any:
        if threading.current_thread() is not threading.main_thread():
            warnings.warn(
                "DarkMessageBox.show_progress wurde nicht im Hauptthread aufgerufen. "
                "GUI-Updates können fehlschlagen.",
                RuntimeWarning,
                stacklevel=2,
            )

        def _create():
            nonlocal dialog, progress, message_label
            try:
                root = parent if parent and parent.winfo_exists() else tk._default_root
                if not root or not root.winfo_exists():
                    logger.error("Kein gültiges root-Fenster für ProgressDialog")
                    return
                dlg = tk.Toplevel(root)
                dlg.title(f"🐉 {title}")
                dlg.configure(bg=CURRENT_THEME.BG_PRIMARY)
                dlg.resizable(False, False)
                dlg.transient(root)
                dlg.grab_set()
                main = tk.Frame(dlg, bg=CURRENT_THEME.BG_PRIMARY, padx=30, pady=25)
                main.pack(fill="both", expand=True)
                msg_lbl = tk.Label(
                    main,
                    text=message,
                    font=Fonts.PRIMARY,
                    bg=CURRENT_THEME.BG_PRIMARY,
                    fg=CURRENT_THEME.TEXT_PRIMARY,
                    justify="center",
                )
                msg_lbl.pack(pady=(0, 20))
                prog = ttk.Progressbar(
                    main,
                    mode="indeterminate" if indeterminate else "determinate",
                    length=300,
                )
                prog.pack(pady=(0, 10))
                prog.start(10)
                cls._center_dialog(dlg, root)
                dialog = dlg
                progress = prog
                message_label = msg_lbl
            except (tk.TclError, RuntimeError) as e:
                logger.warning(f"⚠️ Progress Dialog Error: {e}")

        dialog = None
        progress = None
        message_label = None
        _create()

        class ProgressController:
            __slots__ = ("dialog", "progress", "_message_label")

            def __init__(self):
                self.dialog = dialog
                self.progress = progress
                self._message_label = message_label

            def close(self) -> None:
                """
                Schließt den Fortschrittsdialog sicher.
                Prüft vor der Zerstörung, ob das Fenster noch existiert,
                und fängt mögliche TclErrors ab.
                """
                if self.dialog and self.dialog.winfo_exists():
                    try:
                        if self.progress:
                            self.progress.stop()
                        self.dialog.destroy()
                    except tk.TclError:
                        # Dialog wurde bereits zerstört – ignorieren
                        pass
                    except Exception as e:
                        logger.warning(
                            f"Fehler beim Schließen des Progress-Dialogs: {e}"
                        )
                self.dialog = None
                self.progress = None
                self._message_label = None

            def update_message(self, new_message: str) -> None:
                if self.dialog and self.dialog.winfo_exists() and self._message_label:
                    try:
                        self._message_label.config(text=new_message)
                    except Exception:
                        pass

        return ProgressController()

    @classmethod
    def _show_dialog(
        cls,
        title: str,
        message: str,
        msg_type: str,
        parent: Optional[tk.Tk] = None,
        buttons: bool = False,
        timeout: Optional[int] = None,
    ) -> Optional[bool]:
        try:
            parent = cls._resolve_parent(parent)
            if parent is None:
                return cls._fallback_messagebox(title, message, msg_type, buttons)
            dialog, result, timeout_id = cls._create_base_dialog(
                parent, title, msg_type, message, timeout=timeout
            )
            if buttons:
                cls._add_ok_cancel_buttons(dialog, result, timeout_id, title)
            else:
                cls._add_ok_button(dialog, result, timeout_id)
            dialog.protocol(
                "WM_DELETE_WINDOW",
                lambda: (
                    cls._cancel_timeout(dialog, timeout_id),
                    cls._on_closing(result, False if buttons else True),
                ),
            )
            cls._center_dialog(dialog, parent)
            parent.wait_window(dialog)
            return result["value"]
        except (tk.TclError, RuntimeError, AttributeError) as e:
            logger.warning(f"⚠️ DarkMessageBox Error: {e}")
            return cls._fallback_messagebox(title, message, msg_type, buttons)

    @classmethod
    def _ask_yesno(
        cls,
        title: str,
        message: str,
        parent: Optional[tk.Tk] = None,
        timeout: Optional[int] = None,
    ) -> Optional[bool]:
        try:
            parent = cls._resolve_parent(parent)
            if parent is None:
                import tkinter.messagebox as mb

                return mb.askyesno(title, message)
            dialog, result, timeout_id = cls._create_base_dialog(
                parent, title, "question", message, icon_only=True, timeout=timeout
            )
            btn_frame = tk.Frame(dialog, bg=CURRENT_THEME.BG_PRIMARY)
            btn_frame.pack(fill="x", pady=(10, 0))

            def set_res(val: bool):
                cls._cancel_timeout(dialog, timeout_id)
                result["value"] = val
                if dialog.winfo_exists():
                    dialog.destroy()

            yes_btn = tk.Button(
                btn_frame,
                text="  👍 Ja  ",
                command=lambda: set_res(True),
                bg=CURRENT_THEME.SUCCESS,
                fg=CURRENT_THEME.TEXT_PRIMARY,
                font=("Segoe UI", 10, "bold"),
                relief="flat",
                padx=25,
                pady=10,
                cursor="hand2",
            )
            yes_btn.pack(side="left", expand=True, padx=(0, 10))
            no_btn = tk.Button(
                btn_frame,
                text="  👎 Nein  ",
                command=lambda: set_res(False),
                bg=CURRENT_THEME.ERROR,
                fg=CURRENT_THEME.TEXT_PRIMARY,
                font=("Segoe UI", 10, "bold"),
                relief="flat",
                padx=25,
                pady=10,
                cursor="hand2",
            )
            no_btn.pack(side="right", expand=True)
            dialog.bind("<Return>", lambda e: set_res(True))
            dialog.bind("<Escape>", lambda e: set_res(False))
            dialog.bind("y", lambda e: set_res(True))
            dialog.bind("n", lambda e: set_res(False))
            yes_btn.focus_set()
            dialog.protocol(
                "WM_DELETE_WINDOW",
                lambda: (cls._cancel_timeout(dialog, timeout_id), set_res(False)),
            )
            cls._center_dialog(dialog, parent)
            parent.wait_window(dialog)
            return result["value"]
        except (tk.TclError, RuntimeError, AttributeError):
            import tkinter.messagebox as mb

            return mb.askyesno(title, message)

    @classmethod
    def _create_base_dialog(
        cls,
        parent: tk.Tk,
        title: str,
        msg_type: str,
        message: str,
        icon_only: bool = False,
        timeout: Optional[int] = None,
    ) -> tuple:
        dialog = tk.Toplevel(parent)
        dialog.title(f"🐉 {title}" if not title.startswith("🐉") else title)
        dialog.configure(bg=CURRENT_THEME.BG_PRIMARY)
        dialog.resizable(False, False)
        dialog.transient(parent)
        dialog.grab_set()

        if timeout is not None:
            timeout_id = dialog.after(
                timeout * 1000, lambda: cls._auto_close_dialog(dialog, title)
            )
        else:
            timeout_id = None

        main = tk.Frame(dialog, bg=CURRENT_THEME.BG_PRIMARY, padx=25, pady=25)
        main.pack(fill="both", expand=True)

        if icon_only:
            icon_label = tk.Label(
                main,
                text="❓",
                font=("Segoe UI", 28),
                bg=CURRENT_THEME.BG_PRIMARY,
                fg=CURRENT_THEME.TEXT_ACCENT,
            )
            icon_label.pack(pady=(0, 20))
            msg = tk.Label(
                main,
                text=message,
                font=Fonts.PRIMARY,
                bg=CURRENT_THEME.BG_PRIMARY,
                fg=CURRENT_THEME.TEXT_PRIMARY,
                justify="center",
                wraplength=350,
            )
            msg.pack(pady=(0, 30))
        else:
            content = tk.Frame(main, bg=CURRENT_THEME.BG_PRIMARY)
            content.pack(fill="both", expand=True, pady=(0, 20))
            icon_frame = tk.Frame(content, bg=CURRENT_THEME.BG_PRIMARY, width=60)
            icon_frame.pack(side="left", fill="y")
            icon_frame.pack_propagate(False)
            icons = {
                "info": ("ℹ️", CURRENT_THEME.TEXT_ACCENT),
                "warning": ("⚠️", CURRENT_THEME.WARNING),
                "error": ("❌", CURRENT_THEME.ERROR),
                "question": ("❓", CURRENT_THEME.TEXT_ACCENT),
                "success": ("✅", CURRENT_THEME.SUCCESS),
            }
            icon_char, icon_color = icons.get(
                msg_type, ("💬", CURRENT_THEME.TEXT_PRIMARY)
            )
            tk.Label(
                icon_frame,
                text=icon_char,
                font=("Segoe UI", 24),
                bg=CURRENT_THEME.BG_PRIMARY,
                fg=icon_color,
            ).pack(expand=True)
            msg_frame = tk.Frame(content, bg=CURRENT_THEME.BG_PRIMARY)
            msg_frame.pack(side="left", fill="both", expand=True, padx=(20, 0))
            if len(title) > 30:
                tk.Label(
                    msg_frame,
                    text=title,
                    font=Fonts.SUBTITLE,
                    bg=CURRENT_THEME.BG_PRIMARY,
                    fg=CURRENT_THEME.TEXT_PRIMARY,
                    justify="left",
                    anchor="w",
                ).pack(anchor="w", pady=(0, 10))
            tk.Label(
                msg_frame,
                text=message,
                font=Fonts.PRIMARY,
                bg=CURRENT_THEME.BG_PRIMARY,
                fg=CURRENT_THEME.TEXT_PRIMARY,
                justify="left",
                wraplength=350,
                anchor="w",
            ).pack(fill="x", expand=True, anchor="w")

        result = {"value": None}
        return dialog, result, timeout_id

    @classmethod
    def _add_ok_button(
        cls, dialog: tk.Toplevel, result: dict, timeout_id: Optional[str]
    ) -> tk.Frame:
        btn_frame = tk.Frame(dialog, bg=CURRENT_THEME.BG_PRIMARY)
        btn_frame.pack(fill="x")

        def on_ok():
            cls._cancel_timeout(dialog, timeout_id)
            result["value"] = True
            if dialog.winfo_exists():
                dialog.destroy()

        ok_btn = tk.Button(
            btn_frame,
            text="OK",
            command=on_ok,
            bg=CURRENT_THEME.SUCCESS,
            fg=CURRENT_THEME.TEXT_PRIMARY,
            font=Fonts.BUTTON,
            relief="flat",
            padx=25,
            pady=8,
            cursor="hand2",
            takefocus=True,
        )
        ok_btn.pack(side="right")
        ok_btn.focus_set()
        dialog.bind("<Return>", lambda e: on_ok())
        dialog.bind("<Escape>", lambda e: on_ok())
        dialog.bind("<space>", lambda e: on_ok())
        return btn_frame

    @classmethod
    def _add_ok_cancel_buttons(
        cls, dialog: tk.Toplevel, result: dict, timeout_id: Optional[str], title: str
    ) -> tk.Frame:
        btn_frame = tk.Frame(dialog, bg=CURRENT_THEME.BG_PRIMARY)
        btn_frame.pack(fill="x")

        def set_result(val: bool):
            cls._cancel_timeout(dialog, timeout_id)
            result["value"] = val
            if dialog.winfo_exists():
                dialog.destroy()

        cancel_btn = tk.Button(
            btn_frame,
            text="Abbrechen",
            command=lambda: set_result(False),
            bg=CURRENT_THEME.BG_TERTIARY,
            fg=CURRENT_THEME.TEXT_PRIMARY,
            font=Fonts.BUTTON,
            relief="flat",
            padx=22,
            pady=8,
            cursor="hand2",
            takefocus=True,
        )
        cancel_btn.pack(side="right", padx=(10, 0))
        ok_btn = tk.Button(
            btn_frame,
            text="OK",
            command=lambda: set_result(True),
            bg=CURRENT_THEME.SUCCESS,
            fg=CURRENT_THEME.TEXT_PRIMARY,
            font=Fonts.BUTTON,
            relief="flat",
            padx=25,
            pady=8,
            cursor="hand2",
            takefocus=True,
        )
        ok_btn.pack(side="right")
        dialog.bind("<Return>", lambda e: set_result(True))
        dialog.bind("<Escape>", lambda e: set_result(False))
        dialog.bind("<space>", lambda e: cancel_btn.focus_set())
        is_exit = any(
            w in title.lower() for w in ["beenden", "exit", "quit", "schließen"]
        )
        if is_exit:
            cancel_btn.focus_set()
        else:
            ok_btn.focus_set()
        return btn_frame

    @staticmethod
    def _resolve_parent(parent: Optional[tk.Tk]) -> Optional[tk.Tk]:
        if parent and parent.winfo_exists():
            return parent
        if tk._default_root and tk._default_root.winfo_exists():
            return tk._default_root
        return None

    @staticmethod
    def _center_dialog(dialog: tk.Toplevel, parent: Optional[tk.Tk]) -> None:
        try:
            dialog.update_idletasks()

            # Fenstergröße robust bestimmen
            dlg_w = dialog.winfo_width()
            dlg_h = dialog.winfo_height()

            # Fallback falls Tkinter noch nicht korrekt gemessen hat
            if dlg_w <= 1 or dlg_h <= 1:
                dlg_w = dialog.winfo_reqwidth()
                dlg_h = dialog.winfo_reqheight()

            if parent is None or not parent.winfo_exists():
                # Fallback: zentriert auf dem Bildschirm
                screen_w = dialog.winfo_screenwidth()
                screen_h = dialog.winfo_screenheight()

                x = (screen_w - dlg_w) // 2
                y = (screen_h - dlg_h) // 2

            else:
                parent.update_idletasks()

                parent_x = parent.winfo_rootx()
                parent_y = parent.winfo_rooty()
                parent_w = parent.winfo_width()
                parent_h = parent.winfo_height()

                x = parent_x + (parent_w - dlg_w) // 2
                y = parent_y + (parent_h - dlg_h) // 2

                screen_w = parent.winfo_screenwidth()
                screen_h = parent.winfo_screenheight()

                # Clamp innerhalb Bildschirm
                x = max(10, min(x, screen_w - dlg_w - 10))
                y = max(10, min(y, screen_h - dlg_h - 10))

            dialog.geometry(f"+{x}+{y}")
            dialog.lift()

            try:
                dialog.focus_set()
            except Exception:
                pass

        except Exception as e:
            logger.debug(f"Dialog-Centering fehlgeschlagen: {e}")

    @staticmethod
    def _auto_close_dialog(dialog: tk.Toplevel, title: str) -> None:
        try:
            if dialog and dialog.winfo_exists():
                logger.warning(f"⚠️ Dialog Timeout: '{title}'")
                dialog.destroy()
        except tk.TclError:
            pass

    @staticmethod
    def _cancel_timeout(dialog: tk.Toplevel, timeout_id: Optional[str]) -> None:
        if timeout_id is not None:
            try:
                dialog.after_cancel(timeout_id)
            except Exception:
                pass

    @staticmethod
    def _on_closing(result: dict, close_val: bool) -> None:
        result["value"] = close_val

    @staticmethod
    def _fallback_messagebox(
        title: str, message: str, msg_type: str, buttons: bool = False
    ) -> Optional[bool]:
        try:
            import tkinter.messagebox as mb

            if buttons:
                return mb.askokcancel(title, message)
            getattr(mb, f"show{msg_type}")(title, message)
            return None
        except Exception:
            logger.info(f"💬 {title}: {message}")
            return False if buttons else None


class ToolTip:
    def __init__(self, widget: tk.Widget, text: str, delay: int = 500) -> None:
        self.widget = widget
        self.text = text
        self.delay = delay
        self.tip_window: Optional[tk.Toplevel] = None
        self.after_id: Optional[str] = None
        widget.bind("<Enter>", self.enter)
        widget.bind("<Leave>", self.leave)
        widget.bind("<ButtonPress>", self.leave)

    def enter(self, event: Optional[tk.Event] = None) -> None:
        self.schedule()

    def leave(self, event: Optional[tk.Event] = None) -> None:
        self.unschedule()
        self.hide_tip()

    def schedule(self) -> None:
        self.unschedule()
        self.after_id = self.widget.after(self.delay, self.show_tip)

    def unschedule(self) -> None:
        if self.after_id:
            self.widget.after_cancel(self.after_id)
            self.after_id = None

    def show_tip(self) -> None:
        if self.tip_window or not self.text:
            return
        x, y = self.widget.winfo_pointerxy()
        x += 10
        y += 10
        self.tip_window = tw = tk.Toplevel(self.widget)
        tw.wm_overrideredirect(True)
        tw.wm_geometry(f"+{x}+{y}")
        label = tk.Label(
            tw,
            text=self.text,
            background="#ffffe0",
            relief="solid",
            borderwidth=1,
            font=("Segoe UI", 9),
        )
        label.pack()
        tw.bind("<Leave>", lambda e: self.hide_tip())

    def hide_tip(self) -> None:
        if self.tip_window:
            try:
                self.tip_window.destroy()
            except tk.TclError:
                pass
            self.tip_window = None


class StatisticsDialog(BaseDialog):
    def __init__(self, parent: tk.Tk, stats_text: str):
        self.stats_text = stats_text
        super().__init__(
            parent, "Performance Statistics", width=750, height=600, modal=True
        )

    def build_ui(self) -> None:
        text_widget = scrolledtext.ScrolledText(
            self.main,
            wrap=tk.WORD,
            font=Fonts.MONOSPACE,
            bg=CURRENT_THEME.BG_TERTIARY,
            fg=CURRENT_THEME.TEXT_PRIMARY,
            insertbackground=CURRENT_THEME.TEXT_PRIMARY,
            selectbackground=CURRENT_THEME.COMBO_SELECTION,
            selectforeground=CURRENT_THEME.TEXT_PRIMARY,
            padx=10,
            pady=10,
        )
        text_widget.pack(fill="both", expand=True, pady=(0, 10))
        text_widget.insert("1.0", self.stats_text)
        text_widget.config(state="disabled")
        ContextMenuMixin(text_widget)

        btn_frame = tk.Frame(self.main, bg=CURRENT_THEME.BG_PRIMARY)
        btn_frame.pack(fill="x", pady=(0, 5))

        copy_btn = tk.Button(
            btn_frame,
            text="📋 In Zwischenablage kopieren",
            command=self._copy_to_clipboard,
            bg=CURRENT_THEME.BG_TERTIARY,
            fg=CURRENT_THEME.TEXT_PRIMARY,
            font=Fonts.BUTTON,
            padx=15,
            cursor="hand2",
        )
        copy_btn.pack(side="left", padx=5)

        save_btn = tk.Button(
            btn_frame,
            text="💾 Als Datei speichern",
            command=self._save_to_file,
            bg=CURRENT_THEME.BG_TERTIARY,
            fg=CURRENT_THEME.TEXT_PRIMARY,
            font=Fonts.BUTTON,
            padx=15,
            cursor="hand2",
        )
        save_btn.pack(side="left", padx=5)

        close_btn = tk.Button(
            btn_frame,
            text="Schließen",
            command=self.close,
            bg=CURRENT_THEME.BG_TERTIARY,
            fg=CURRENT_THEME.TEXT_PRIMARY,
            font=Fonts.BUTTON,
            padx=15,
            cursor="hand2",
        )
        close_btn.pack(side="right", padx=5)

        self._text_widget = text_widget

    def _copy_to_clipboard(self) -> None:
        try:
            self.dialog.clipboard_clear()
            self.dialog.clipboard_append(self.stats_text)
            if hasattr(self, "status_label"):
                self.status_label.config(text="✅ In Zwischenablage kopiert")
            else:
                DarkMessageBox.showinfo(
                    "Kopiert",
                    "Statistik wurde in die Zwischenablage kopiert.",
                    self.dialog,
                    timeout=2,
                )
        except Exception as e:
            logger.warning(f"Fehler beim Kopieren: {e}")

    def _save_to_file(self) -> None:
        from tkinter import filedialog

        filename = filedialog.asksaveasfilename(
            defaultextension=".txt",
            filetypes=[("Text files", "*.txt"), ("All files", "*.*")],
            title="Statistik speichern",
            initialfile=f"dragon_stats_{datetime.now().strftime('%Y%m%d_%H%M%S')}.txt",
        )
        if filename:
            try:
                with open(filename, "w", encoding="utf-8") as f:
                    f.write(self.stats_text)
                DarkMessageBox.showinfo(
                    "Gespeichert",
                    f"Statistik gespeichert:\n{filename}",
                    self.dialog,
                    timeout=2,
                )
            except Exception as e:
                DarkMessageBox.showerror(
                    "Fehler", f"Speichern fehlgeschlagen:\n{e}", self.dialog
                )


class SummarizeDialog(BaseDialog):
    """
    Dialog zur Zusammenfassung von Texten mit Ollama (thread‑sicher, optimiert).

    Features:
        - Automatische Erkennung verfügbarer Modelle
        - Mehrsprachige Zusammenfassung (Deutsch, Englisch, Spanisch, Koreanisch,
          Chinesisch, Japanisch) – erweiterbar über zentrale Prompt‑Map
        - Parallele Chunk‑Verarbeitung langer Texte (> 2000 Wörter) mit begrenzter Parallelität
        - Fortschrittsbalken und detaillierte Statusanzeige
        - Abbruchmöglichkeit während der gesamten Verarbeitung (kooperativ)
        - Blacklist‑Filterung der finalen Zusammenfassung
        - Speichern und Kopieren der Ergebnisse
        - Direkte Übersetzung der Zusammenfassung
        - Vollständige Ressourcenfreigabe beim Schließen
        - Wiederholungslogik bei Server‑Fehlern (exponentieller Backoff)
        - Token‑Limit‑Warnung für große Prompts
        - Debug‑Ausgaben bei --debug=3
    """

    # -------------------------------------------------------------------------
    # Sprach‑Prompt‑Map (zentrale Definition, leicht erweiterbar)
    # -------------------------------------------------------------------------
    SUMMARY_LANGUAGE_PROMPTS = {
        "Deutsch": (
            "Fasse den folgenden Text in 3-5 Sätzen auf Deutsch zusammen. "
            "Konzentriere dich auf die Hauptaussagen, ignoriere Wiederholungen und Füllwörter. "
            "Verwende vollständige, idiomatische Sätze.\n\n"
            "WICHTIG: Die Ausgabe MUSS auf DEUTSCH erfolgen und darf KEINE Zeichen aus anderen "
            "Sprachen (wie Chinesisch, Japanisch oder Koreanisch) enthalten. "
            "Fachbegriffe wie 'Sakura' oder 'Kimchi' können als Lehnwörter verwendet werden, "
            "aber bitte in lateinischer Schrift.\n\n"
            "Achte darauf, dass Begriffe, die im Deutschen mehrere Bedeutungen haben könnten (z.B. ‚Verhältnis‘), "
            "im jeweiligen Zusammenhang eindeutig sind. Wähle stattdessen präzisere Ausdrücke."
        ),
        "Englisch": (
            "Summarize the following text in 3-5 sentences in English. "
            "Focus on the main points, ignore repetitions and filler words. "
            "Use complete, idiomatic sentences.\n\n"
            "IMPORTANT: The output MUST be in ENGLISH and must NOT contain characters from other "
            "languages (like Chinese, Japanese, or Korean). Loanwords are acceptable in Latin script."
        ),
        "Spanisch": (
            "Resume el siguiente texto en 3-5 oraciones en español. "
            "Concéntrate en las ideas principales, ignora repeticiones y palabras de relleno. "
            "Utiliza oraciones completas e idiomáticas.\n\n"
            "IMPORTANTE: La salida DEBE estar en ESPAÑOL y NO debe contener caracteres de otros "
            "idiomas (como chino, japonés o coreano). Los préstamos son aceptables en escritura latina."
        ),
        "Koreanisch": (
            "다음 텍스트를 한국어로 3-5문장으로 요약하세요. "
            "핵심 내용에 집중하고, 반복과 불용어는 무시하세요. "
            "완전하고 관용적인 문장을 사용하세요.\n\n"
            "중요: 출력은 반드시 한국어로 작성되어야 하며 다른 언어(예: 중국어, 일본어)의 문자가 포함되어서는 안 됩니다. "
            "외래어는 라틴 문자로 표기해도 됩니다."
        ),
        "Chinesisch": (
            "将以下文本用中文总结成3-5句话。专注于主要观点，忽略重复和填充词。"
            "使用完整、地道的句子。\n\n"
            "重要：输出必须是中文，不能包含其他语言的字符。外来词可以用拉丁字母表示。"
        ),
        "Japanisch": (
            "以下のテキストを日本語で3～5文に要約してください。"
            "主要なポイントに焦点を当て、繰り返しや不要な言葉は無視してください。"
            "完全で自然な日本語の文を使用してください。\n\n"
            "重要: 出力は必ず日本語で行い、他の言語（中国語、韓国語など）の文字を含めないでください。"
            "外来語はカタカナで表記しても構いません。"
        ),
    }

    SUPPORTED_SUMMARY_LANGUAGES = list(SUMMARY_LANGUAGE_PROMPTS.keys())

    # -------------------------------------------------------------------------
    # Initialisierung
    # -------------------------------------------------------------------------
    def __init__(self, parent: Any, text: str, gui_ref: Any) -> None:
        self.text = text
        self.gui = gui_ref
        self.stream_title = None

        # Stream‑Titel ermitteln
        if self.gui and hasattr(self.gui, "current_stream_info") and self.gui.current_stream_info:
            self.stream_title = self.gui.current_stream_info.title
        if not self.stream_title and self.gui and hasattr(self.gui, "last_stream_title") and self.gui.last_stream_title:
            self.stream_title = self.gui.last_stream_title
        if not self.stream_title and hasattr(self.gui, "stream_title_label"):
            try:
                label_text = self.gui.stream_title_label.cget("text")
                if label_text and label_text.startswith("📡 "):
                    self.stream_title = label_text[2:].strip()
            except Exception:
                pass
        if not self.stream_title:
            self.stream_title = ""

        # Abbruch‑Event
        self._request_cancel = threading.Event()

        # OllamaSummarizer (Hauptinstanz für finale Zusammenfassung)
        self.summarizer = OllamaSummarizer(
            parent,
            model=self.gui.advanced_settings.summarize_model,
            host=self.gui.advanced_settings.ollama_host,
            cache_manager=self.gui.app_context.cache_manager,
        )

        self.saved_temp = self.gui.advanced_settings.summarize_temperature
        self.saved_model = self.gui.advanced_settings.summarize_model

        # Thread‑sichere Datenstrukturen
        self._lock = threading.RLock()
        self._chunk_results: List[str] = []
        self._chunks: List[str] = []
        self._current_chunk = 0
        self._prompt = ""
        self._temp = 0.1
        self.full_summary = ""
        self._destroyed = False

        # Executor für parallele Chunk‑Verarbeitung (wird bei Bedarf erstellt)
        self._chunk_executor: Optional[ThreadPoolExecutor] = None
        self._chunk_semaphore = threading.BoundedSemaphore(value=2)  # max. 2 parallele Chunks

        super().__init__(
            parent, "Zusammenfassung mit Ollama", width=800, height=700, modal=True
        )

    # -------------------------------------------------------------------------
    # UI‑Aufbau
    # -------------------------------------------------------------------------
    def build_ui(self) -> None:
        if not self.summarizer.is_server_reachable():
            DarkMessageBox.showwarning(
                "Ollama nicht erreichbar",
                "Der Ollama-Server läuft nicht oder ist nicht erreichbar.\n"
                "Bitte starte 'ollama serve' und versuche es erneut.",
                parent=self.parent,
            )
            self.close()
            return

        # 1. Modell‑Auswahl
        model_frame = tk.Frame(self.main, bg=CURRENT_THEME.BG_PRIMARY)
        model_frame.pack(fill="x", pady=5)

        tk.Label(
            model_frame,
            text="Modell:",
            bg=CURRENT_THEME.BG_PRIMARY,
            fg=CURRENT_THEME.TEXT_PRIMARY,
        ).pack(side="left")

        self.model_var = tk.StringVar(value=self.saved_model)
        available = self.summarizer.get_available_models()
        if available:
            preferred = ["qwen2.5:7b", "glm4:9b", "llama3.1:8b"]
            values = []
            for pref in preferred:
                if pref in available:
                    values.append(pref)
            for m in available:
                if m not in values:
                    values.append(m)
            self.model_combo = ttk.Combobox(
                model_frame,
                textvariable=self.model_var,
                values=values,
                width=20,
                state="readonly",
                style="Dark.TCombobox",
            )
