    # -------------------------------------------------------------------------
    #  Sektion: Übersetzung (inkl. Reflection)
    # -------------------------------------------------------------------------
    def _create_translation_section(self, row: int) -> None:
        trans_frame = tk.LabelFrame(
            self.settings_frame,
            text="🌐 Übersetzung",
            padx=10,
            pady=8,
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            font=("Segoe UI", 8, "bold"),
        )
        trans_frame.grid(row=row, column=0, sticky="ew", pady=5, padx=5)
        trans_frame.columnconfigure(1, weight=1)
        trans_frame.columnconfigure(3, weight=1)

        tk.Label(
            trans_frame,
            text="Engine:",
            anchor="w",
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            font=("Segoe UI", 8),
        ).grid(row=0, column=0, sticky="w", pady=1)
        self.engine_var = tk.StringVar(
            value=getattr(self.gui.advanced_settings, "translation_engine", "google")
        )
        self.engine_combo = ttk.Combobox(
            trans_frame,
            textvariable=self.engine_var,
            values=["google", "ollama", "argos"],
            width=self.COMBO_WIDTH_SMALL,
            state="readonly",
            style="Dark.TCombobox",
        )
        self.engine_combo.grid(row=0, column=1, sticky="w", pady=1)

        tk.Label(
            trans_frame,
            text="Ollama Model:",
            anchor="w",
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            font=("Segoe UI", 8),
        ).grid(row=0, column=2, sticky="w", pady=1)
        self.ollama_model_var = tk.StringVar(
            value=getattr(self.gui.advanced_settings, "ollama_model", "llama3.1:8b")
        )
        self.ollama_model_combo = ttk.Combobox(
            trans_frame,
            textvariable=self.ollama_model_var,
            values=[],
            width=15,
            state="normal",
            style="Dark.TCombobox",
        )
        self.ollama_model_combo.grid(row=0, column=3, sticky="w", pady=1)
        ToolTip(
            self.ollama_model_combo,
            "Ollama-Modell (kann auch manuell eingegeben werden)",
        )

        tk.Label(
            trans_frame,
            text="Ollama Host:",
            anchor="w",
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            font=("Segoe UI", 8),
        ).grid(row=1, column=0, sticky="w", pady=1)
        host_frame = tk.Frame(trans_frame, bg=self.gui.current_theme.BG_SECONDARY)
        host_frame.grid(row=1, column=1, columnspan=3, sticky="ew", pady=1)
        host_frame.columnconfigure(0, weight=1)

        self.ollama_host_var = tk.StringVar(
            value=getattr(
                self.gui.advanced_settings, "ollama_host", "http://localhost:11434"
            )
        )
        self.ollama_host_entry = tk.Entry(
            host_frame,
            textvariable=self.ollama_host_var,
            width=30,
            bg=self.gui.current_theme.BG_TERTIARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            insertbackground=self.gui.current_theme.TEXT_PRIMARY,
            font=("Segoe UI", 8),
        )
        self.ollama_host_entry.pack(side="left", fill="x", expand=True, padx=(0, 5))

        def test_ollama() -> None:
            host = self.ollama_host_var.get().strip()
            if not host:
                host = "http://localhost:11434"
            try:
                import requests

                r = requests.get(f"{host}/api/tags", timeout=3)
                if r.status_code == 200:
                    DarkMessageBox.showinfo(
                        "Success", "Ollama server is reachable!", self.parent
                    )
                else:
                    DarkMessageBox.showerror(
                        "Error", f"Ollama returned status {r.status_code}", self.parent
                    )
            except Exception as e:
                DarkMessageBox.showerror(
                    "Error", f"Connection failed: {e}", self.parent
                )

        self.test_btn = tk.Button(
            host_frame,
            text="Test",
            command=test_ollama,
            bg=self.gui.current_theme.BG_TERTIARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            relief="flat",
            padx=5,
            font=("Segoe UI", 8),
        )
        self.test_btn.pack(side="right")

        # Reflection-Checkbox
        self.reflection_cb = tk.Checkbutton(
            trans_frame,
            text="🔄 Reflection (selbstkorrigierende Übersetzung)",
            variable=self.reflection_var,
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            selectcolor=self.gui.current_theme.BG_TERTIARY,
            activebackground=self.gui.current_theme.BG_SECONDARY,
            font=("Segoe UI", 8),
        )
        self.reflection_cb.grid(row=2, column=0, columnspan=4, sticky="w", pady=5)
        ToolTip(
            self.reflection_cb,
            "Aktiviert eine zweistufige Übersetzung mit Selbstreflexion (nur für Ollama-Engine).\n"
            "Verbessert die Qualität erheblich, benötigt aber zwei API-Calls pro Übersetzung."
        )

        self._fetch_ollama_models()

