            left_controls,
            text="🔄",
            command=self.gui_ref.toggle_layout,
            bg=self.gui_ref.current_theme.BG_TERTIARY,
            fg=self.gui_ref.current_theme.TEXT_PRIMARY,
            relief="flat",
            bd=0,
            font=("Segoe UI", 9),
