def global_exception_handler(exc_type, exc_value, exc_traceback):
    if issubclass(exc_type, KeyboardInterrupt):
        sys.__excepthook__(exc_type, exc_value, exc_traceback)
        return
    logger.critical(
        "Unhandled exception in main thread",
        exc_info=(exc_type, exc_value, exc_traceback),
    )
    try:
        import tkinter.messagebox as mb

        mb.showerror(
            "Dragon Whisperer - Unerwarteter Fehler",
            f"Ein unerwarteter Fehler ist aufgetreten:\n\n{exc_value}\n\n"
            "Details in der Konsole.",
        )
    except Exception:
        pass
    sys.__excepthook__(exc_type, exc_value, exc_traceback)


def thread_exception_handler(args):
    logger.critical(
        f"Unhandled exception in thread {args.thread.name}: {args.exc_value}",
        exc_info=(args.exc_type, args.exc_value, args.exc_traceback),
    )


sys.excepthook = global_exception_handler
threading.excepthook = thread_exception_handler

